//! State transition function (`chain::stf`, §7).

use core::fmt;
use std::collections::BTreeMap;

use ledger::{BalanceDelta, JobId, Ledger, LedgerError, StateCategory};
use primitives::{Atoms, ShareWeight};
use scheduler::{OwnerId, ShareID, dhondt_allocation};
use wire::{
    CategoryDelta, Digest, FeeTransition, GenesisConfig, JobTransaction, LeaseAssignment,
    OwnerReward, SettlementReceipt,
};

use crate::core_adapter::{
    JobValidationError, LABEL_LEDGER, compute_result_digest, digest_to_hash, domain_hash,
    validate_job_stateless,
};

/// Registered Fresh Work share in `NodeState` (§7.1).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ShareRecord {
    /// ShareID.
    pub work_id: Digest,
    /// Beneficiary.
    pub owner: u64,
    /// `w_s`, fixed by the share target at the share's height.
    pub weight: u64,
    /// Height the share was mined at.
    pub height: u64,
    /// Height of the block that registered it.
    pub included_at: u64,
}

/// Admitted commercial job awaiting settlement in `NodeState` (§7.1).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OpenJob {
    /// Job identifier.
    pub job_id: u64,
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Height of `JOB_ADMIT_AND_LEASE`.
    pub admitted_at: u64,
    /// Lease owner (executor by attribution).
    pub owner: u64,
    /// Leased ShareID.
    pub share_id: Digest,
    /// Executor remuneration.
    pub v_exec: u64,
    /// Data-availability remuneration.
    pub v_da: u64,
    /// Refund share.
    pub v_ref: u64,
    /// Exact dot product computed at admission.
    pub result: i128,
}

/// Immutable per-block state snapshot (§7.1).
#[derive(Clone, Debug)]
pub struct NodeState {
    /// Height of the block this state follows.
    pub height: u64,
    /// The eight-category core ledger.
    pub ledger: Ledger,
    /// Registered shares by ShareID (pruned per §6.7).
    pub shares: BTreeMap<Digest, ShareRecord>,
    /// Admitted, unsettled jobs by `job_id`.
    pub open_jobs: BTreeMap<u64, OpenJob>,
    /// Used `tx_id`s with their expiry height (pruned once expired).
    pub used_tx: BTreeMap<Digest, u64>,
    /// Used `job_id`s with their expiry height (pruned once expired).
    pub used_job_ids: BTreeMap<u64, u64>,
    /// Atoms booked at the last epoch boundary, paid at the next one.
    pub pending_payout: u64,
}

impl NodeState {
    /// Builds the genesis `NodeState` at height 0 (§3.4).
    pub fn genesis(ledger: Ledger) -> Self {
        Self {
            height: 0,
            ledger,
            shares: BTreeMap::new(),
            open_jobs: BTreeMap::new(),
            used_tx: BTreeMap::new(),
            used_job_ids: BTreeMap::new(),
            pending_payout: 0,
        }
    }

    /// Returns the mature D'Hondt lease cohort for a block at height `h`, sorted by
    /// ShareID (§6.7).
    pub fn lease_cohort(&self, h: u64, g: &GenesisConfig) -> Vec<ShareRecord> {
        let Some(max_inc) = h.checked_sub(g.share_maturity_depth) else {
            return Vec::new();
        };
        let min_inc = h.saturating_sub(g.snapshot_window);
        self.shares_included_in(min_inc, max_inc)
    }

    /// Returns the shares weighed at the epoch boundary `h`: those included in the
    /// previous epoch, sorted by ShareID (§6.7).
    pub fn epoch_shares(&self, h: u64, g: &GenesisConfig) -> Vec<ShareRecord> {
        let Some(max_inc) = h.checked_sub(1) else {
            return Vec::new();
        };
        self.shares_included_in(h.saturating_sub(g.blocks_per_epoch), max_inc)
    }

    fn shares_included_in(&self, min_inc: u64, max_inc: u64) -> Vec<ShareRecord> {
        // `shares` is a BTreeMap keyed by work_id, so the result is in ShareID order.
        self.shares
            .values()
            .filter(|s| (min_inc..=max_inc).contains(&s.included_at))
            .cloned()
            .collect()
    }
}

/// Share pre-validated (Stage A and B) for `apply_body` (§7.2).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedShare {
    /// ShareID.
    pub work_id: Digest,
    /// Beneficiary.
    pub owner: u64,
    /// `w_s`.
    pub weight: u64,
    /// Height the share was mined at.
    pub height: u64,
}

/// Derived body commitments produced by `apply_body` (§5.3, §7.2).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DerivedBody {
    /// `leases[i]` belongs to `jobs[i]`.
    pub leases: Vec<LeaseAssignment>,
    /// Receipts of the jobs settled in this block.
    pub receipts: Vec<SettlementReceipt>,
    /// Every ledger operation, in execution order.
    pub fee_transitions: Vec<FeeTransition>,
    /// Commitment to the post-state.
    pub ledger_digest: Digest,
}

/// Errors produced by `apply_body` (§7.2). Any error rejects the whole block.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum StfError {
    /// A core ledger operation was rejected.
    Ledger(LedgerError),
    /// More than `max_jobs_per_block` jobs.
    TooManyJobs(usize),
    /// More than `max_shares_per_block` shares.
    TooManyShares(usize),
    /// Jobs are not strictly increasing by `tx_id`.
    JobsNotSortedOrUnique,
    /// Shares are not strictly increasing by `work_id`.
    SharesNotSortedOrUnique,
    /// A job fails stateless validation.
    InvalidJob(JobValidationError),
    /// A job is included after its expiry height.
    JobExpired {
        /// The job.
        job_id: u64,
        /// Its expiry height.
        expiry: u64,
        /// The including height.
        height: u64,
    },
    /// The `tx_id` was already used.
    DuplicateTx(Digest),
    /// The `job_id` was already used.
    DuplicateJobId(u64),
    /// Jobs were included while the mature share cohort is empty.
    EmptyLeaseCohort,
    /// The D'Hondt scheduler rejected the cohort or did not fill every slot.
    SchedulerError(String),
    /// The share is already registered.
    DuplicateShare(Digest),
}

impl fmt::Display for StfError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StfError::Ledger(e) => write!(f, "ledger error: {e}"),
            StfError::TooManyJobs(n) => write!(f, "too many jobs in block: {n}"),
            StfError::TooManyShares(n) => write!(f, "too many shares in block: {n}"),
            StfError::JobsNotSortedOrUnique => {
                write!(f, "jobs must be strictly sorted by tx_id")
            }
            StfError::SharesNotSortedOrUnique => {
                write!(f, "shares must be strictly sorted by work_id")
            }
            StfError::InvalidJob(e) => write!(f, "invalid job: {e}"),
            StfError::JobExpired {
                job_id,
                expiry,
                height,
            } => write!(f, "job {job_id} expired at {expiry} (height {height})"),
            StfError::DuplicateTx(id) => write!(f, "duplicate tx_id {id:?}"),
            StfError::DuplicateJobId(id) => write!(f, "duplicate job_id {id}"),
            StfError::EmptyLeaseCohort => {
                write!(f, "cannot admit jobs with an empty mature share cohort")
            }
            StfError::SchedulerError(msg) => write!(f, "scheduler error: {msg}"),
            StfError::DuplicateShare(id) => write!(f, "duplicate share work_id {id:?}"),
        }
    }
}

impl std::error::Error for StfError {}

impl From<LedgerError> for StfError {
    fn from(e: LedgerError) -> Self {
        StfError::Ledger(e)
    }
}

/// Converts a `ledger::BalanceDelta` to a wire `CategoryDelta` in `StateCategory::ALL` order (§5.7).
pub fn to_category_delta(delta: &BalanceDelta) -> CategoryDelta {
    StateCategory::ALL.map(|c| delta.get(c))
}

/// Computes `ledger_digest` from the post-state (§3.3, §5.8): 15 fixed-width parts.
pub fn compute_ledger_digest(state: &NodeState) -> Digest {
    let ledger = &state.ledger;
    let balances = StateCategory::ALL.map(|c| ledger.balance(c).get().to_be_bytes());
    let head = [state.height.to_be_bytes(), ledger.epoch().to_be_bytes()];
    let tail = [
        ledger.segregated_dust().get().to_be_bytes(),
        (ledger.fee_lots().len() as u64).to_be_bytes(),
        (ledger.locked_fees().len() as u64).to_be_bytes(),
        state.pending_payout.to_be_bytes(),
    ];
    let parts: Vec<&[u8]> = head
        .iter()
        .chain(&balances)
        .chain(&tail)
        .map(|p| p.as_slice())
        .collect();
    domain_hash(LABEL_LEDGER, &parts)
}

/// Normative state transition function `apply_body` (§7.2).
///
/// Works on a clone of `parent`; on any error the clone is discarded, so a block
/// applies all-or-nothing (WP 7.14).
pub fn apply_body(
    parent: &NodeState,
    g: &GenesisConfig,
    h: u64,
    jobs: &[JobTransaction],
    shares: &[VerifiedShare],
) -> Result<(NodeState, DerivedBody), StfError> {
    if jobs.len() as u64 > g.max_jobs_per_block {
        return Err(StfError::TooManyJobs(jobs.len()));
    }
    if shares.len() as u64 > g.max_shares_per_block {
        return Err(StfError::TooManyShares(shares.len()));
    }
    if shares.windows(2).any(|w| w[0].work_id >= w[1].work_id) {
        return Err(StfError::SharesNotSortedOrUnique);
    }
    if let Some(dup) = shares
        .iter()
        .find(|sh| parent.shares.contains_key(&sh.work_id))
    {
        return Err(StfError::DuplicateShare(dup.work_id));
    }

    let mut s = parent.clone();
    let mut fee_transitions = Vec::new();
    let mut receipts = Vec::new();
    let mut leases = Vec::with_capacity(jobs.len());

    s.ledger.advance_to(h)?;

    // (1) Epoch boundary, WP (7.24)-(7.25)
    if h >= 1 && h.is_multiple_of(g.blocks_per_epoch) {
        let e = s.ledger.epoch();
        let (d_mat, lots) = s.ledger.reserve_mature()?;
        fee_transitions.push(FeeTransition::ReserveMature {
            epoch: e,
            matured_lots: lots.into_iter().map(|l| l.0).collect(),
            delta: to_category_delta(&d_mat),
        });

        let d_rew = s.ledger.fw_reward(Atoms(s.pending_payout))?;
        fee_transitions.push(FeeTransition::FwReward {
            epoch: e,
            amount: s.pending_payout,
            delta: to_category_delta(&d_rew),
        });

        let epoch_cohort = s.epoch_shares(h, g);
        let weights: Vec<ShareWeight> = epoch_cohort.iter().map(|sh| sh.weight).collect();
        let (d_book, payout) = s.ledger.book_epoch(&weights)?;

        let mut owner_totals: BTreeMap<u64, u64> = BTreeMap::new();
        for (sh, reward) in epoch_cohort.iter().zip(&payout.per_share) {
            if reward.get() > 0 {
                *owner_totals.entry(sh.owner).or_insert(0) += reward.get();
            }
        }
        let per_owner: Vec<OwnerReward> = owner_totals
            .into_iter()
            .map(|(owner, atoms)| OwnerReward { owner, atoms })
            .collect();

        s.pending_payout = payout.booked.get();
        fee_transitions.push(FeeTransition::EpochBooked {
            epoch: e,
            budget: payout.budget.get(),
            booked: payout.booked.get(),
            dust: payout.dust.get(),
            lots: payout.lots.len() as u32,
            shares: weights.len() as u32,
            per_owner,
            delta: to_category_delta(&d_book),
        });
    }

    // (2) Settle the jobs admitted at h - settle_delay, in job_id order
    let due_ids: Vec<u64> = s
        .open_jobs
        .values()
        .filter(|j| j.admitted_at.saturating_add(g.settle_delay) == h)
        .map(|j| j.job_id)
        .collect();
    for job_id in due_ids {
        let Some(j) = s.open_jobs.remove(&job_id) else {
            continue;
        };
        let d = s.ledger.result_settle(
            JobId(j.job_id),
            Atoms(j.v_exec),
            Atoms(j.v_da),
            Atoms(j.v_ref),
        )?;
        fee_transitions.push(FeeTransition::ResultSettle {
            job_id: j.job_id,
            v_exec: j.v_exec,
            v_da: j.v_da,
            v_ref: j.v_ref,
            delta: to_category_delta(&d),
        });
        receipts.push(SettlementReceipt {
            job_id: j.job_id,
            tx_id: j.tx_id,
            executor_owner: j.owner,
            admitted_at: j.admitted_at,
            result: j.result,
            result_digest: compute_result_digest(j.job_id, j.result),
            v_exec: j.v_exec,
            v_da: j.v_da,
            v_ref: j.v_ref,
        });
    }

    // (3) Fund the new jobs (sorted by tx_id)
    let mut validated: Vec<(Digest, u64, i128)> = Vec::with_capacity(jobs.len());
    for tx in jobs {
        let (tx_id, job_id, deposit, dot_result) =
            validate_job_stateless(tx).map_err(StfError::InvalidJob)?;
        if validated.last().is_some_and(|&(prev, _, _)| prev >= tx_id) {
            return Err(StfError::JobsNotSortedOrUnique);
        }
        if h > tx.expiry_height {
            return Err(StfError::JobExpired {
                job_id,
                expiry: tx.expiry_height,
                height: h,
            });
        }
        if s.used_tx.contains_key(&tx_id) {
            return Err(StfError::DuplicateTx(tx_id));
        }
        if s.used_job_ids.contains_key(&job_id) || validated.iter().any(|v| v.1 == job_id) {
            return Err(StfError::DuplicateJobId(job_id));
        }

        let d =
            s.ledger
                .escrow_fund_and_queue(JobId(job_id), Atoms(deposit), Atoms(tx.queue_fee))?;
        fee_transitions.push(FeeTransition::EscrowFundAndQueue {
            job_id,
            deposit,
            queue_fee: tx.queue_fee,
            delta: to_category_delta(&d),
        });
        validated.push((tx_id, job_id, dot_result));
    }

    // (4) Allocate leases with D'Hondt over the mature cohort, WP (6.4)
    if !jobs.is_empty() {
        let cohort = s.lease_cohort(h, g);
        if cohort.is_empty() {
            return Err(StfError::EmptyLeaseCohort);
        }
        let share_ids: Vec<ShareID> = cohort
            .iter()
            .map(|sh| ShareID {
                id: digest_to_hash(&sh.work_id),
                weight: sh.weight,
                owner: OwnerId(sh.owner),
            })
            .collect();

        let alloc = dhondt_allocation(&share_ids, jobs.len())
            .map_err(|e| StfError::SchedulerError(e.to_string()))?;
        if alloc.assigned() != jobs.len() {
            return Err(StfError::SchedulerError(
                "D'Hondt did not assign all requested job slots".to_string(),
            ));
        }

        for ((tx, &(tx_id, job_id, dot_result)), &slot) in
            jobs.iter().zip(&validated).zip(&alloc.slots)
        {
            let share = cohort.get(slot).ok_or_else(|| {
                StfError::SchedulerError(format!("slot index {slot} outside the cohort"))
            })?;
            let d = s
                .ledger
                .job_admit_and_lease(JobId(job_id), Atoms(tx.base_fee))?;
            fee_transitions.push(FeeTransition::JobAdmitAndLease {
                job_id,
                base_fee: tx.base_fee,
                owner: share.owner,
                delta: to_category_delta(&d),
            });
            leases.push(LeaseAssignment {
                job_id,
                share_id: share.work_id,
                owner: share.owner,
            });
            s.open_jobs.insert(
                job_id,
                OpenJob {
                    job_id,
                    tx_id,
                    admitted_at: h,
                    owner: share.owner,
                    share_id: share.work_id,
                    v_exec: tx.v_exec,
                    v_da: tx.v_da,
                    v_ref: tx.v_ref,
                    result: dot_result,
                },
            );
            s.used_tx.insert(tx_id, tx.expiry_height);
            s.used_job_ids.insert(job_id, tx.expiry_height);
        }
    }

    // (5) Register the shares of the body
    for sh in shares {
        s.shares.insert(
            sh.work_id,
            ShareRecord {
                work_id: sh.work_id,
                owner: sh.owner,
                weight: sh.weight,
                height: sh.height,
                included_at: h,
            },
        );
    }

    // (6) Prune, check, commit
    s.used_tx.retain(|_, &mut expiry| expiry >= h);
    s.used_job_ids.retain(|_, &mut expiry| expiry >= h);
    let retain = g
        .snapshot_window
        .max(g.blocks_per_epoch)
        .max(g.share_inclusion_window)
        .saturating_add(1);
    if let Some(min_keep) = h.checked_sub(retain) {
        s.shares.retain(|_, sh| sh.included_at >= min_keep);
    }

    s.ledger.check_invariants()?;
    s.height = h;
    let ledger_digest = compute_ledger_digest(&s);

    Ok((
        s,
        DerivedBody {
            leases,
            receipts,
            fee_transitions,
            ledger_digest,
        },
    ))
}
EOF

cat << 'EOF' > chain/src/template.rs
//! Block template building (`chain::template`, §7.4).

use std::sync::Arc;
use wire::{
    Block, BlockBody, BlockHeader, CORE_PROTOCOL_VERSION, Digest, FwContext, GENERATOR_VERSION,
    GenesisConfig, JobTransaction, PLACEHOLDER_SUITE_ID, ShareProof, Target, codec,
};
use work::FreshWorkIds;

use crate::core_adapter::{
    compute_body_root, compute_difficulty_context, compute_job_ids, compute_miner_policy_digest,
    compute_payout_policy_digest, compute_program_and_air_ids, fresh_work_ids_to_digests,
};
use crate::difficulty::{ChainView, expected_targets, share_weight};
use crate::stf::{NodeState, StfError, VerifiedShare, apply_body};

/// Mining template published to the `ConsensusEngine` (§7.4, §8.5).
#[derive(Clone, Debug)]
pub struct Template {
    /// Increases with every published template.
    pub generation: u64,
    /// Context of the next block, with `attempt_nonce = 0`.
    pub context: FwContext,
    /// Body committed by `context.body_core_root`.
    pub body: Arc<BlockBody>,
    /// `Θ_B` of the next height.
    pub seal_target: Target,
    /// `Θ_S` of the next height.
    pub share_target: Target,
    /// Beneficiary of everything mined on this template.
    pub miner_owner: u64,
}

impl Template {
    /// Returns a copy of `context` with `attempt_nonce` set to `nonce`.
    pub fn context_with_nonce(&self, nonce: u64) -> FwContext {
        let mut ctx = self.context.clone();
        ctx.attempt_nonce = nonce;
        ctx
    }

    /// Seals this template into a `Block` using the given `nonce` and `FreshWorkIds`.
    pub fn seal(&self, nonce: u64, ids: &FreshWorkIds) -> Block {
        let d = fresh_work_ids_to_digests(ids);
        Block {
            header: BlockHeader {
                context: self.context_with_nonce(nonce),
                output_root: d.output_root,
                work_id: d.work_id,
                block_id: d.block_id,
                share_ticket: d.share_ticket,
                seal_ticket: d.seal_ticket,
                seal_target: self.seal_target,
                share_target: self.share_target,
                miner_owner: self.miner_owner,
            },
            body: (*self.body).clone(),
        }
    }

    /// Packages an attempt on this template into a `ShareProof` using `nonce` and `FreshWorkIds`.
    pub fn share(&self, nonce: u64, ids: &FreshWorkIds) -> ShareProof {
        let d = fresh_work_ids_to_digests(ids);
        ShareProof {
            context: self.context_with_nonce(nonce),
            owner: self.miner_owner,
            output_root: d.output_root,
            work_id: d.work_id,
            share_ticket: d.share_ticket,
            share_target: self.share_target,
        }
    }

    /// True when `other` would make the miners evaluate exactly the same contexts.
    pub fn same_work_as(&self, other: &Template) -> bool {
        self.context == other.context
            && self.seal_target == other.seal_target
            && self.share_target == other.share_target
            && self.miner_owner == other.miner_owner
    }
}

/// Own shares that satisfy the §6.7 inclusion rules for a block at height `h` on `chain`,
/// sorted by `work_id`, unique, at most `max_shares_per_block`.
fn includable_shares(
    genesis: &GenesisConfig,
    genesis_id: Digest,
    chain: &impl ChainView,
    tip_state: &NodeState,
    own_shares: &[ShareProof],
    h: u64,
) -> Vec<ShareProof> {
    let (program_id, air_id) = compute_program_and_air_ids();
    let mut shares: Vec<ShareProof> = own_shares
        .iter()
        .filter(|sh| {
            let s = sh.context.height;
            if s < 1 || s >= h || s < h.saturating_sub(genesis.share_inclusion_window) {
                return false;
            }
            if tip_state.shares.contains_key(&sh.work_id) {
                return false;
            }
            let (exp_seal, exp_share) = chain.targets_at(s);
            let c = &sh.context;
            sh.owner >= 1
                && c.chain_id == genesis.chain_id
                && c.genesis_id == genesis_id
                && c.protocol_version == CORE_PROTOCOL_VERSION
                && c.crypto_suite_id == PLACEHOLDER_SUITE_ID
                && c.program_id == program_id
                && c.air_id == air_id
                && c.generator_version == GENERATOR_VERSION
                && c.parent_canonical_id == chain.block_id_at(s - 1)
                && c.stable_anchor_id == chain.block_id_at(s.saturating_sub(genesis.anchor_depth))
                && c.miner_policy_digest == compute_miner_policy_digest(sh.owner)
                && c.payout_policy_digest == compute_payout_policy_digest(sh.owner)
                && c.parent_derived_difficulty_context
                    == compute_difficulty_context(exp_seal, exp_share)
                && sh.share_target == exp_share
        })
        .cloned()
        .collect();
    shares.sort_by_key(|s| s.work_id);
    shares.dedup_by_key(|s| s.work_id);
    shares.truncate(genesis.max_shares_per_block as usize);
    shares
}

/// The `VerifiedShare` view of a share proof.
pub fn verified_share(sh: &ShareProof) -> VerifiedShare {
    VerifiedShare {
        work_id: sh.work_id,
        owner: sh.owner,
        weight: share_weight(sh.share_target),
        height: sh.context.height,
    }
}

/// Runs `apply_body` and assembles the body with its derived fields.
fn derive_body(
    tip_state: &NodeState,
    genesis: &GenesisConfig,
    h: u64,
    jobs: Vec<JobTransaction>,
    shares: &[ShareProof],
) -> Result<BlockBody, StfError> {
    let verified: Vec<VerifiedShare> = shares.iter().map(verified_share).collect();
    let (_, derived) = apply_body(tip_state, genesis, h, &jobs, &verified)?;
    Ok(BlockBody {
        jobs,
        shares: shares.to_vec(),
        leases: derived.leases,
        receipts: derived.receipts,
        fee_transitions: derived.fee_transitions,
        ledger_digest: derived.ledger_digest,
    })
}

/// Builds a new mining `Template` on top of the tip at `tip_height` of `chain` (§7.4).
///
/// Jobs are taken in FIFO order (no fee priority, WP 6.16) as long as the body stays
/// valid; unfundable jobs are skipped and stay in the mempool. Errors only if even an
/// empty body cannot be derived, which would indicate a corrupted tip state.
#[allow(clippy::too_many_arguments)]
pub fn build_template(
    generation: u64,
    genesis: &GenesisConfig,
    genesis_id: Digest,
    chain: &impl ChainView,
    tip_height: u64,
    tip_state: &NodeState,
    mempool_fifo: &[JobTransaction],
    own_shares: &[ShareProof],
    miner_owner: u64,
    now_bucket: u64,
) -> Result<Template, StfError> {
    let h = tip_height + 1;
    let mut shares = includable_shares(genesis, genesis_id, chain, tip_state, own_shares, h);
    let verified: Vec<VerifiedShare> = shares.iter().map(verified_share).collect();
    if apply_body(tip_state, genesis, h, &[], &verified).is_err() {
        shares.clear();
    }

    // Greedily add jobs in FIFO order; the body itself stays sorted by tx_id (§7.4).
    let mut selected: Vec<(Digest, JobTransaction)> = Vec::new();
    for tx in mempool_fifo {
        if selected.len() as u64 >= genesis.max_jobs_per_block {
            break;
        }
        let Ok((tx_id, _)) = compute_job_ids(tx) else {
            continue;
        };
        let Err(pos) = selected.binary_search_by_key(&tx_id, |(id, _)| *id) else {
            continue;
        };
        let mut candidate = selected.clone();
        candidate.insert(pos, (tx_id, tx.clone()));
        let jobs: Vec<JobTransaction> = candidate.iter().map(|(_, j)| j.clone()).collect();
        let verified: Vec<VerifiedShare> = shares.iter().map(verified_share).collect();
        if apply_body(tip_state, genesis, h, &jobs, &verified).is_ok() {
            selected = candidate;
        }
    }

    let mut jobs: Vec<JobTransaction> = selected.into_iter().map(|(_, j)| j).collect();
    let mut body = derive_body(tip_state, genesis, h, jobs.clone(), &shares)?;
    let size_limit = genesis.max_block_bytes.saturating_sub(4096) as usize;
    while !jobs.is_empty() && codec::encode(&body).map_or(usize::MAX, |b| b.len()) > size_limit {
        jobs.pop();
        body = derive_body(tip_state, genesis, h, jobs.clone(), &shares)?;
    }

    let (seal_target, share_target) = expected_targets(h, chain, genesis);
    let body_core_root = compute_body_root(&body).map_err(StfError::SchedulerError)?;
    let (program_id, air_id) = compute_program_and_air_ids();
    let context = FwContext {
        chain_id: genesis.chain_id,
        genesis_id,
        protocol_version: CORE_PROTOCOL_VERSION,
        crypto_suite_id: PLACEHOLDER_SUITE_ID,
        program_id,
        air_id,
        generator_version: GENERATOR_VERSION,
        parent_canonical_id: chain.block_id_at(tip_height),
        stable_anchor_id: chain.block_id_at(h.saturating_sub(genesis.anchor_depth)),
        height: h,
        miner_policy_digest: compute_miner_policy_digest(miner_owner),
        payout_policy_digest: compute_payout_policy_digest(miner_owner),
        attempt_nonce: 0,
        body_core_root,
        parent_derived_difficulty_context: compute_difficulty_context(seal_target, share_target),
        time_bucket: chain.time_bucket_at(tip_height).max(now_bucket),
    };

    Ok(Template {
        generation,
        context,
        body: Arc::new(body),
        seal_target,
        share_target,
        miner_owner,
    })
}
EOF

cat << 'EOF' > chain/src/tree.rs
//! BlockTree, Stage B validation, fork choice, and block summaries (`chain::tree`, §6, §8.3).

use core::fmt;
use std::collections::HashMap;
use std::sync::Arc;

use ledger::StateCategory;
use wire::{
    Block, CORE_PROTOCOL_VERSION, Digest, FeeTransition, GENERATOR_VERSION, GenesisConfig,
    MAX_FUTURE_SECS, MAX_REORG_DEPTH, PLACEHOLDER_SUITE_ID, ShareProof, Target, codec,
};

use crate::core_adapter::{
    ClaimedWork, Lottery, WorkError, compute_body_root, compute_difficulty_context,
    compute_job_ids, compute_miner_policy_digest, compute_payout_policy_digest,
    compute_program_and_air_ids, top128, validate_genesis, verify_fresh_work,
};
use crate::difficulty::{ChainView, expected_targets, seal_weight, share_target_for, share_weight};
use crate::stf::{NodeState, ShareRecord, VerifiedShare, apply_body};
use crate::template::verified_share;

/// Metadata stored per validated block in `BlockTree` (§8.3).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BlockMeta {
    /// `block_id` (or `genesis_id` for the virtual height 0).
    pub id: Digest,
    /// Parent `block_id` (`Digest::ZERO` for genesis).
    pub parent: Digest,
    /// Height.
    pub height: u64,
    /// Context field 16.
    pub time_bucket: u64,
    /// `Θ_B` of this height.
    pub seal_target: Target,
    /// `Θ_S` of this height.
    pub share_target: Target,
    /// `work_of(seal_target)`.
    pub seal_weight: u128,
    /// Sum of seal weights from genesis.
    pub cumulative_weight: u128,
    /// Beneficiary (0 for genesis).
    pub miner_owner: u64,
}

/// Summary of an admitted job inside a block for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JobSummary {
    /// Job identifier.
    pub job_id: u64,
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Lease owner.
    pub executor_owner: u64,
    /// Escrow deposit.
    pub deposit: u64,
    /// Queue fee.
    pub queue_fee: u64,
    /// Base Fee.
    pub base_fee: u64,
}

/// Summary of a settlement receipt inside a block for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReceiptSummary {
    /// Settled job.
    pub job_id: u64,
    /// Exact dot product.
    pub result: i128,
    /// Lease owner.
    pub executor_owner: u64,
    /// Height of admission.
    pub admitted_at: u64,
}

/// Summary of an included share inside a block for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ShareSummary {
    /// ShareID.
    pub work_id: Digest,
    /// Beneficiary.
    pub owner: u64,
    /// Height the share was mined at.
    pub height: u64,
    /// `w_s`.
    pub weight: u64,
}

/// Summary of a block and its post-state balances for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BlockSummary {
    /// Height.
    pub height: u64,
    /// `block_id`.
    pub block_id: Digest,
    /// Parent `block_id`.
    pub parent_id: Digest,
    /// `stable_anchor_id`.
    pub anchor_id: Digest,
    /// Beneficiary.
    pub miner_owner: u64,
    /// Context field 16.
    pub time_bucket: u64,
    /// Winning nonce.
    pub attempt_nonce: u64,
    /// Ledger epoch after the block.
    pub epoch: u64,
    /// `θ_B`.
    pub seal_ticket: Digest,
    /// Seal weight.
    pub seal_weight: u128,
    /// Cumulative chain weight.
    pub cumulative_weight: u128,
    /// Admitted jobs.
    pub jobs: Vec<JobSummary>,
    /// Settled jobs.
    pub receipts: Vec<ReceiptSummary>,
    /// Included share proofs.
    pub shares: Vec<ShareSummary>,
    /// Whether the header's own work registered as a share.
    pub header_share: bool,
    /// Ledger transitions in execution order.
    pub fee_transitions: Vec<FeeTransition>,
    /// The 8 category balances after the block, in `StateCategory::ALL` order.
    pub balances_after: [u64; StateCategory::COUNT],
    /// Sum of `balances_after` (always `M`).
    pub total_after: u128,
}

/// View over one branch of a `BlockTree`, from genesis up to a given block.
///
/// Heights at or below `fork_height` are on the canonical chain; the side branch above
/// it is stored explicitly, so building the view costs only the side-branch length.
pub struct AncestorChainView<'a> {
    tree: &'a BlockTree,
    fork_height: u64,
    branch: Vec<Digest>, // heights fork_height+1 ..= top, ascending
}

impl AncestorChainView<'_> {
    /// Highest height covered by the view.
    pub fn top_height(&self) -> u64 {
        self.fork_height + self.branch.len() as u64
    }

    fn meta_at(&self, h: u64) -> Option<&BlockMeta> {
        self.tree.metas.get(&self.block_id_at(h))
    }
}

impl ChainView for AncestorChainView<'_> {
    fn block_id_at(&self, h: u64) -> Digest {
        if h <= self.fork_height {
            self.tree.canonical_id_at(h).unwrap_or(Digest::ZERO)
        } else {
            self.branch
                .get((h - self.fork_height - 1) as usize)
                .copied()
                .unwrap_or(Digest::ZERO)
        }
    }

    fn time_bucket_at(&self, h: u64) -> u64 {
        self.meta_at(h)
            .map_or(self.tree.genesis.genesis_time_bucket, |m| m.time_bucket)
    }

    fn targets_at(&self, h: u64) -> (Target, Target) {
        self.meta_at(h).map_or_else(
            || self.tree.genesis_targets(),
            |m| (m.seal_target, m.share_target),
        )
    }
}

impl ChainView for BlockTree {
    fn block_id_at(&self, h: u64) -> Digest {
        self.canonical_id_at(h).unwrap_or(Digest::ZERO)
    }

    fn time_bucket_at(&self, h: u64) -> u64 {
        self.canonical_meta_at(h)
            .map_or(self.genesis.genesis_time_bucket, |m| m.time_bucket)
    }

    fn targets_at(&self, h: u64) -> (Target, Target) {
        self.canonical_meta_at(h).map_or_else(
            || self.genesis_targets(),
            |m| (m.seal_target, m.share_target),
        )
    }
}

/// Validation or tree error (§6.8).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TreeError {
    /// The block is already known.
    Duplicate,
    /// The parent is not in the tree.
    Orphan {
        /// The missing parent.
        parent: Digest,
    },
    /// The fork point is deeper than `MAX_REORG_DEPTH` or its snapshot was pruned.
    TooDeep,
    /// The block's `time_bucket` is too far in the future; retry later.
    Deferred {
        /// The block's time bucket.
        time_bucket: u64,
    },
    /// The block violates a consensus rule.
    Invalid(String),
}

impl fmt::Display for TreeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TreeError::Duplicate => write!(f, "duplicate block"),
            TreeError::Orphan { parent } => write!(f, "unknown parent {parent:?}"),
            TreeError::TooDeep => write!(f, "parent fork exceeds MAX_REORG_DEPTH or is pruned"),
            TreeError::Deferred { time_bucket } => {
                write!(f, "block time_bucket {time_bucket} is in the future")
            }
            TreeError::Invalid(reason) => write!(f, "invalid block: {reason}"),
        }
    }
}

impl std::error::Error for TreeError {}

fn invalid(reason: impl Into<String>) -> TreeError {
    TreeError::Invalid(reason.into())
}

/// Outcome of inserting a verified block into `BlockTree`.
#[derive(Clone, Debug)]
pub struct InsertOutcome {
    /// Metadata of the inserted block.
    pub meta: BlockMeta,
    /// Whether the block became the new tip.
    pub tip_changed: bool,
    /// Blocks that joined the canonical chain, ascending.
    pub connected: Vec<Arc<Block>>,
    /// Blocks that left the canonical chain, old tip first.
    pub disconnected: Vec<Arc<Block>>,
}

/// Multi-branch block tree and canonical chain tracker (§6, §8.3).
pub struct BlockTree {
    genesis: GenesisConfig,
    genesis_id: Digest,
    metas: HashMap<Digest, BlockMeta>,
    blocks: HashMap<Digest, Arc<Block>>,
    states: HashMap<Digest, Arc<NodeState>>,
    summaries: HashMap<Digest, BlockSummary>,
    canonical: Vec<Digest>, // index == height
    tip: Digest,
}

impl BlockTree {
    /// Creates a new `BlockTree` initialized at the virtual height 0 (§3.4).
    pub fn new(genesis: GenesisConfig) -> Result<Self, String> {
        let (_params, ledger, genesis_id) = validate_genesis(&genesis)?;
        let seal = genesis.initial_seal_target;
        let genesis_meta = BlockMeta {
            id: genesis_id,
            parent: Digest::ZERO,
            height: 0,
            time_bucket: genesis.genesis_time_bucket,
            seal_target: seal,
            share_target: share_target_for(seal, genesis.share_ratio),
            seal_weight: 0,
            cumulative_weight: 0,
            miner_owner: 0,
        };
        Ok(Self {
            genesis,
            genesis_id,
            metas: HashMap::from([(genesis_id, genesis_meta)]),
            blocks: HashMap::new(),
            states: HashMap::from([(genesis_id, Arc::new(NodeState::genesis(ledger)))]),
            summaries: HashMap::new(),
            canonical: vec![genesis_id],
            tip: genesis_id,
        })
    }

    /// The genesis configuration.
    pub fn genesis(&self) -> &GenesisConfig {
        &self.genesis
    }

    /// `genesis_id`, the `block_id` of height 0.
    pub fn genesis_id(&self) -> Digest {
        self.genesis_id
    }

    fn genesis_targets(&self) -> (Target, Target) {
        let seal = self.genesis.initial_seal_target;
        (seal, share_target_for(seal, self.genesis.share_ratio))
    }

    /// Current tip `block_id`.
    pub fn tip_id(&self) -> Digest {
        self.tip
    }

    /// Current tip metadata.
    pub fn tip_meta(&self) -> &BlockMeta {
        self.metas
            .get(&self.tip)
            .expect("invariant: the tip is always in the tree")
    }

    /// Current tip post-state.
    pub fn tip_state(&self) -> Arc<NodeState> {
        self.states
            .get(&self.tip)
            .cloned()
            .expect("invariant: the tip state is never pruned")
    }

    /// Whether the block is in the tree (any branch).
    pub fn has_block(&self, id: &Digest) -> bool {
        self.metas.contains_key(id)
    }

    /// A block by id (any branch).
    pub fn get_block(&self, id: &Digest) -> Option<Arc<Block>> {
        self.blocks.get(id).cloned()
    }

    /// Metadata by id (any branch).
    pub fn get_meta(&self, id: &Digest) -> Option<&BlockMeta> {
        self.metas.get(id)
    }

    /// Post-state by id, if not pruned.
    pub fn get_state(&self, id: &Digest) -> Option<Arc<NodeState>> {
        self.states.get(id).cloned()
    }

    /// Canonical `block_id` at `height`.
    pub fn canonical_id_at(&self, height: u64) -> Option<Digest> {
        self.canonical.get(usize::try_from(height).ok()?).copied()
    }

    fn canonical_meta_at(&self, height: u64) -> Option<&BlockMeta> {
        self.metas.get(&self.canonical_id_at(height)?)
    }

    /// Canonical block at `height` (`None` for height 0).
    pub fn canonical_block_at(&self, height: u64) -> Option<Arc<Block>> {
        self.blocks.get(&self.canonical_id_at(height)?).cloned()
    }

    /// Summaries of canonical blocks with height `< before` (default: all), newest first.
    pub fn canonical_summaries(&self, before: Option<u64>, limit: usize) -> Vec<BlockSummary> {
        let tip_h = self.tip_meta().height;
        let max_h = before.map_or(tip_h, |b| b.saturating_sub(1).min(tip_h));
        (1..=max_h)
            .rev()
            .filter_map(|h| self.summaries.get(&self.canonical_id_at(h)?).cloned())
            .take(limit)
            .collect()
    }

    /// Whether a not-yet-expired transaction is included on the canonical chain.
    ///
    /// The tip state remembers every used `tx_id` until its expiry height, after which
    /// the transaction could not be included again anyway.
    pub fn is_tx_on_canonical(&self, tx_id: &Digest) -> bool {
        self.tip_state().used_tx.contains_key(tx_id)
    }

    fn is_canonical(&self, meta: &BlockMeta) -> bool {
        self.canonical_id_at(meta.height) == Some(meta.id)
    }

    /// Builds an `AncestorChainView` of the branch ending at `top_id`.
    pub fn ancestor_view(&self, top_id: Digest) -> Option<AncestorChainView<'_>> {
        let mut branch = Vec::new();
        let mut meta = self.metas.get(&top_id)?;
        while !self.is_canonical(meta) {
            branch.push(meta.id);
            meta = self.metas.get(&meta.parent)?;
        }
        branch.reverse();
        Some(AncestorChainView {
            tree: self,
            fork_height: meta.height,
            branch,
        })
    }

    /// Runs §6.8 steps 1–6: size and ordering, duplicate, parent, depth, Stage B and time.
    ///
    /// `now_unix_secs = None` skips the local future-time check (disk replay, tests).
    pub fn pre_validate(&self, block: &Block, now_unix_secs: Option<u64>) -> Result<(), TreeError> {
        // Step 1: size and list caps, sorting and uniqueness
        let encoded = codec::encode(block).map_err(|e| invalid(e.to_string()))?;
        if encoded.len() as u64 > self.genesis.max_block_bytes {
            return Err(invalid(format!(
                "block size {} exceeds max_block_bytes {}",
                encoded.len(),
                self.genesis.max_block_bytes
            )));
        }
        let body = &block.body;
        if body.jobs.len() as u64 > self.genesis.max_jobs_per_block {
            return Err(invalid("too many jobs in block"));
        }
        if body.shares.len() as u64 > self.genesis.max_shares_per_block {
            return Err(invalid("too many shares in block"));
        }
        let mut prev_tx: Option<Digest> = None;
        for tx in &body.jobs {
            let (tx_id, _) =
                compute_job_ids(tx).map_err(|e| invalid(format!("job id failed: {e}")))?;
            if prev_tx.is_some_and(|p| p >= tx_id) {
                return Err(invalid("jobs must be strictly sorted by tx_id"));
            }
            prev_tx = Some(tx_id);
        }
        if body.shares.windows(2).any(|w| w[0].work_id >= w[1].work_id) {
            return Err(invalid("shares must be strictly sorted by work_id"));
        }

        // Step 2: duplicate
        if self.metas.contains_key(&block.header.block_id) {
            return Err(TreeError::Duplicate);
        }

        // Step 3: parent in tree
        let ctx = &block.header.context;
        let parent_id = ctx.parent_canonical_id;
        let Some(parent_meta) = self.metas.get(&parent_id) else {
            return Err(TreeError::Orphan { parent: parent_id });
        };

        // Step 4: parent snapshot missing or fork deeper than MAX_REORG_DEPTH
        let Some(parent_state) = self.states.get(&parent_id) else {
            return Err(TreeError::TooDeep);
        };
        if self.tip_meta().height.saturating_sub(parent_meta.height) > MAX_REORG_DEPTH {
            return Err(TreeError::TooDeep);
        }

        // Step 5: Stage B for the header (§6.3) and for each share (§6.3, §6.7)
        let h = parent_meta.height + 1;
        let (program_id, air_id) = compute_program_and_air_ids();
        if ctx.height != h {
            return Err(invalid(format!("expected height {h}, got {}", ctx.height)));
        }
        self.check_context_constants(ctx, program_id, air_id)?;
        if block.header.miner_owner < 1 {
            return Err(invalid("miner_owner must be >= 1"));
        }
        if ctx.miner_policy_digest != compute_miner_policy_digest(block.header.miner_owner)
            || ctx.payout_policy_digest != compute_payout_policy_digest(block.header.miner_owner)
        {
            return Err(invalid("policy digest does not match miner_owner"));
        }
        if ctx.body_core_root != compute_body_root(body).map_err(invalid)? {
            return Err(invalid("body_core_root mismatch"));
        }
        if ctx.time_bucket < parent_meta.time_bucket {
            return Err(invalid("time_bucket regressed below parent"));
        }

        let view = self
            .ancestor_view(parent_id)
            .ok_or_else(|| invalid("missing ancestor chain"))?;
        if ctx.stable_anchor_id != view.block_id_at(h.saturating_sub(self.genesis.anchor_depth)) {
            return Err(invalid("stable_anchor_id mismatch"));
        }
        let (exp_seal, exp_share) = expected_targets(h, &view, &self.genesis);
        if block.header.seal_target != exp_seal {
            return Err(invalid("seal_target mismatch"));
        }
        if block.header.share_target != exp_share {
            return Err(invalid("share_target mismatch"));
        }
        if ctx.parent_derived_difficulty_context != compute_difficulty_context(exp_seal, exp_share)
        {
            return Err(invalid("parent_derived_difficulty_context mismatch"));
        }
        for sh in &body.shares {
            self.validate_share_stage_b(sh, h, &view, parent_state, program_id, air_id)?;
        }

        // Step 6: future time_bucket (§6.6), a local rule
        if let Some(now_secs) = now_unix_secs {
            let now_bucket = now_secs / self.genesis.time_bucket_secs;
            let max_lead = MAX_FUTURE_SECS / self.genesis.time_bucket_secs;
            if ctx.time_bucket > now_bucket.saturating_add(max_lead) {
                return Err(TreeError::Deferred {
                    time_bucket: ctx.time_bucket,
                });
            }
        }
        Ok(())
    }

    fn check_context_constants(
        &self,
        ctx: &wire::FwContext,
        program_id: Digest,
        air_id: Digest,
    ) -> Result<(), TreeError> {
        let checks = [
            (ctx.chain_id == self.genesis.chain_id, "chain_id"),
            (ctx.genesis_id == self.genesis_id, "genesis_id"),
            (
                ctx.protocol_version == CORE_PROTOCOL_VERSION,
                "protocol_version",
            ),
            (
                ctx.crypto_suite_id == PLACEHOLDER_SUITE_ID,
                "crypto_suite_id",
            ),
            (ctx.program_id == program_id, "program_id"),
            (ctx.air_id == air_id, "air_id"),
            (
                ctx.generator_version == GENERATOR_VERSION,
                "generator_version",
            ),
        ];
        match checks.iter().find(|(ok, _)| !ok) {
            Some((_, field)) => Err(invalid(format!("{field} mismatch"))),
            None => Ok(()),
        }
    }

    fn validate_share_stage_b(
        &self,
        sh: &ShareProof,
        h: u64,
        view: &AncestorChainView<'_>,
        parent_state: &NodeState,
        program_id: Digest,
        air_id: Digest,
    ) -> Result<(), TreeError> {
        let s = sh.context.height;
        if s < 1 || s >= h || s < h.saturating_sub(self.genesis.share_inclusion_window) {
            return Err(invalid(format!(
                "share height {s} outside inclusion window at block height {h}"
            )));
        }
        if parent_state.shares.contains_key(&sh.work_id) {
            return Err(invalid("share work_id already registered"));
        }
        if sh.owner < 1 {
            return Err(invalid("share owner must be >= 1"));
        }
        let c = &sh.context;
        self.check_context_constants(c, program_id, air_id)
            .map_err(|e| invalid(format!("share: {e}")))?;
        if c.parent_canonical_id != view.block_id_at(s - 1) {
            return Err(invalid("share parent_canonical_id mismatch"));
        }
        if c.stable_anchor_id != view.block_id_at(s.saturating_sub(self.genesis.anchor_depth)) {
            return Err(invalid("share stable_anchor_id mismatch"));
        }
        if c.miner_policy_digest != compute_miner_policy_digest(sh.owner)
            || c.payout_policy_digest != compute_payout_policy_digest(sh.owner)
        {
            return Err(invalid("share policy digest mismatch"));
        }
        let (exp_seal, exp_share) = view.targets_at(s);
        if sh.share_target != exp_share {
            return Err(invalid("share_target mismatch"));
        }
        if c.parent_derived_difficulty_context != compute_difficulty_context(exp_seal, exp_share) {
            return Err(invalid("share difficulty context mismatch"));
        }
        Ok(())
    }

    /// Runs Stage A (VerifyFW) synchronously on the header and all shares (§6.2).
    pub fn verify_stage_a(block: &Block) -> Result<(), WorkError> {
        verify_fresh_work(
            &block.header.context,
            &ClaimedWork::from_header(&block.header),
            block.header.seal_target,
            Lottery::Seal,
        )?;
        for sh in &block.body.shares {
            verify_fresh_work(
                &sh.context,
                &ClaimedWork::from_share(sh),
                sh.share_target,
                Lottery::Share,
            )?;
        }
        Ok(())
    }

    /// Applies §6.8 steps 8–9: `apply_body`, header share registration, insertion and fork
    /// choice. The caller must have run `pre_validate` and Stage A (or trust the block).
    pub fn apply_verified_block(&mut self, block: Arc<Block>) -> Result<InsertOutcome, TreeError> {
        let id = block.header.block_id;
        if self.metas.contains_key(&id) {
            return Err(TreeError::Duplicate);
        }
        let parent_id = block.header.context.parent_canonical_id;
        let parent_meta = self
            .metas
            .get(&parent_id)
            .ok_or(TreeError::Orphan { parent: parent_id })?
            .clone();
        let parent_state = self.states.get(&parent_id).ok_or(TreeError::TooDeep)?;

        // Step 8: apply_body and require the body's derived fields to match
        let h = parent_meta.height + 1;
        let verified: Vec<VerifiedShare> = block.body.shares.iter().map(verified_share).collect();
        let (mut post_state, derived) =
            apply_body(parent_state, &self.genesis, h, &block.body.jobs, &verified)
                .map_err(|e| invalid(e.to_string()))?;
        if derived.leases != block.body.leases {
            return Err(invalid("derived leases mismatch"));
        }
        if derived.receipts != block.body.receipts {
            return Err(invalid("derived receipts mismatch"));
        }
        if derived.fee_transitions != block.body.fee_transitions {
            return Err(invalid("derived fee_transitions mismatch"));
        }
        if derived.ledger_digest != block.body.ledger_digest {
            return Err(invalid("derived ledger_digest mismatch"));
        }

        // Step 9: the header's own work is a share if θ_S < Θ_S (§6.7)
        let header_share = top128(&block.header.share_ticket) < block.header.share_target.0;
        if header_share {
            post_state
                .shares
                .entry(block.header.work_id)
                .or_insert(ShareRecord {
                    work_id: block.header.work_id,
                    owner: block.header.miner_owner,
                    weight: share_weight(block.header.share_target),
                    height: h,
                    included_at: h,
                });
        }

        let sw = seal_weight(&block.header);
        let cw = parent_meta
            .cumulative_weight
            .checked_add(sw)
            .ok_or_else(|| invalid("cumulative_weight overflow"))?;
        let meta = BlockMeta {
            id,
            parent: parent_id,
            height: h,
            time_bucket: block.header.context.time_bucket,
            seal_target: block.header.seal_target,
            share_target: block.header.share_target,
            seal_weight: sw,
            cumulative_weight: cw,
            miner_owner: block.header.miner_owner,
        };

        // Fork choice (§6.5): strictly heavier wins; a tie keeps the current tip.
        // The reorg path is computed before anything is inserted, so a too-deep
        // reorg leaves the tree untouched.
        let reorg = if cw > self.tip_meta().cumulative_weight {
            Some(self.reorg_path(parent_id)?)
        } else {
            None
        };

        let summary = build_summary(&block, &meta, &post_state, header_share)?;
        self.metas.insert(id, meta.clone());
        self.blocks.insert(id, block.clone());
        self.states.insert(id, Arc::new(post_state));
        self.summaries.insert(id, summary);

        let Some((fork_height, branch)) = reorg else {
            return Ok(InsertOutcome {
                meta,
                tip_changed: false,
                connected: Vec::new(),
                disconnected: Vec::new(),
            });
        };
        let keep = (fork_height + 1) as usize;
        let disconnected = self.canonical[keep..]
            .iter()
            .rev()
            .filter_map(|old| self.blocks.get(old).cloned())
            .collect();
        self.canonical.truncate(keep);
        self.canonical.extend(&branch);
        self.canonical.push(id);
        let connected = branch
            .iter()
            .chain(std::iter::once(&id))
            .filter_map(|new| self.blocks.get(new).cloned())
            .collect();
        self.tip = id;
        self.prune_old_snapshots();
        Ok(InsertOutcome {
            meta,
            tip_changed: true,
            connected,
            disconnected,
        })
    }

    /// Fork height and side branch (ascending, up to and including `parent_id`) of a new
    /// tip whose parent is `parent_id`.
    fn reorg_path(&self, parent_id: Digest) -> Result<(u64, Vec<Digest>), TreeError> {
        let view = self.ancestor_view(parent_id).ok_or(TreeError::TooDeep)?;
        if self.tip_meta().height.saturating_sub(view.fork_height) > MAX_REORG_DEPTH {
            return Err(TreeError::TooDeep);
        }
        Ok((view.fork_height, view.branch))
    }

    fn prune_old_snapshots(&mut self) {
        let Some(cutoff) = self.tip_meta().height.checked_sub(MAX_REORG_DEPTH) else {
            return;
        };
        let (metas, genesis_id) = (&self.metas, self.genesis_id);
        self.states
            .retain(|id, _| *id == genesis_id || metas.get(id).is_some_and(|m| m.height >= cutoff));
    }
}

fn build_summary(
    block: &Block,
    meta: &BlockMeta,
    post_state: &NodeState,
    header_share: bool,
) -> Result<BlockSummary, TreeError> {
    let mut jobs = Vec::with_capacity(block.body.jobs.len());
    for (i, tx) in block.body.jobs.iter().enumerate() {
        let (tx_id, job_id) = compute_job_ids(tx).map_err(invalid)?;
        let deposit = tx
            .checked_deposit()
            .ok_or_else(|| invalid("job deposit overflow"))?;
        jobs.push(JobSummary {
            job_id,
            tx_id,
            executor_owner: block.body.leases.get(i).map_or(0, |l| l.owner),
            deposit,
            queue_fee: tx.queue_fee,
            base_fee: tx.base_fee,
        });
    }
    let receipts = block
        .body
        .receipts
        .iter()
        .map(|r| ReceiptSummary {
            job_id: r.job_id,
            result: r.result,
            executor_owner: r.executor_owner,
            admitted_at: r.admitted_at,
        })
        .collect();
    let shares = block
        .body
        .shares
        .iter()
        .map(|s| ShareSummary {
            work_id: s.work_id,
            owner: s.owner,
            height: s.context.height,
            weight: share_weight(s.share_target),
        })
        .collect();

    Ok(BlockSummary {
        height: meta.height,
        block_id: meta.id,
        parent_id: meta.parent,
        anchor_id: block.header.context.stable_anchor_id,
        miner_owner: meta.miner_owner,
        time_bucket: meta.time_bucket,
        attempt_nonce: block.header.context.attempt_nonce,
        epoch: post_state.ledger.epoch(),
        seal_ticket: block.header.seal_ticket,
        seal_weight: meta.seal_weight,
        cumulative_weight: meta.cumulative_weight,
        jobs,
        receipts,
        shares,
        header_share,
        fee_transitions: block.body.fee_transitions.clone(),
        balances_after: StateCategory::ALL.map(|c| post_state.ledger.balance(c).get()),
        total_after: post_state.ledger.total(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core_adapter::{compute_client_digest, fw_context_to_core};
    use crate::template::build_template;
    use primitives::TOTAL_SUPPLY;
    use wire::{DifficultyMode, JobPayload, JobTransaction};
    use work::FreshWorkIds;

    fn test_genesis() -> GenesisConfig {
        let mut g = GenesisConfig::default_testnet(1_700_000_000);
        g.initial_seal_target = Target(u128::MAX);
        g.share_ratio = 1;
        g.difficulty = DifficultyMode::Fixed;
        g.blocks_per_epoch = 4;
        g.settle_delay = 2;
        g.share_maturity_depth = 1;
        g.snapshot_window = 20;
        g.share_inclusion_window = 10;
        g
    }

    fn mine_one(
        tree: &BlockTree,
        parent_id: Digest,
        owner: u64,
        mempool: &[JobTransaction],
        nonce: u64,
        time_bucket: u64,
    ) -> Block {
        let anc = tree.ancestor_view(parent_id).unwrap();
        let parent_meta = tree.get_meta(&parent_id).unwrap();
        let parent_state = tree.get_state(&parent_id).unwrap();
        let tpl = build_template(
            1,
            tree.genesis(),
            tree.genesis_id(),
            &anc,
            parent_meta.height,
            &parent_state,
            mempool,
            &[],
            owner,
            time_bucket,
        )
        .unwrap();
        let ctx = fw_context_to_core(&tpl.context_with_nonce(nonce)).unwrap();
        let inst = ctx.instance();
        let z = inst.x.product(&inst.y);
        tpl.seal(nonce, &FreshWorkIds::derive(&ctx, &z))
    }

    fn sample_job(nonce: u64, expiry_height: u64) -> JobTransaction {
        JobTransaction {
            client: compute_client_digest("alice").unwrap(),
            queue_fee: 100_000_000,
            base_fee: 1_000_000_000,
            v_exec: 8_000_000_000,
            v_da: 500_000_000,
            v_ref: 500_000_000,
            expiry_height,
            nonce,
            payload: JobPayload::ExactDot {
                xs: (1..=512).map(|i| i as f64).collect(),
                ys: (1..=512).rev().map(|i| i as f64).collect(),
            },
        }
    }

    #[test]
    fn stf_job_lifecycle_and_tamper_rejection() {
        let g = test_genesis();
        let mut tree = BlockTree::new(g.clone()).unwrap();
        let tx = sample_job(1, 100);

        // Epoch 1 (boundary h = 4) books the header shares of blocks 1..=3; that booking
        // is paid into U at the epoch-2 boundary h = 8. Until then the founder tranches
        // lock all of U, so the template leaves the job out.
        let b1 = mine_one(
            &tree,
            tree.tip_id(),
            1,
            std::slice::from_ref(&tx),
            0,
            1_700_000_001,
        );
        assert!(b1.body.jobs.is_empty());
        tree.pre_validate(&b1, None).unwrap();
        BlockTree::verify_stage_a(&b1).unwrap();
        tree.apply_verified_block(Arc::new(b1)).unwrap();

        for h in 2..=7 {
            let b = mine_one(
                &tree,
                tree.tip_id(),
                1,
                std::slice::from_ref(&tx),
                h,
                1_700_000_000 + h,
            );
            assert!(b.body.jobs.is_empty(), "job must wait for spendable U");
            tree.pre_validate(&b, None).unwrap();
            let out = tree.apply_verified_block(Arc::new(b)).unwrap();
            assert!(out.tip_changed);
            assert_eq!(
                tree.tip_state().ledger.total(),
                u128::from(TOTAL_SUPPLY.get())
            );
        }

        // At h = 8 the epoch-1 booking is paid and a mature cohort exists: the job is admitted.
        let b8 = mine_one(
            &tree,
            tree.tip_id(),
            1,
            std::slice::from_ref(&tx),
            8,
            1_700_000_008,
        );
        assert_eq!(b8.body.jobs.len(), 1);
        assert_eq!(b8.body.leases.len(), 1);

        let mut tampered = b8.clone();
        tampered.header.miner_owner = 999;
        assert!(tree.pre_validate(&tampered, None).is_err());

        tree.pre_validate(&b8, None).unwrap();
        BlockTree::verify_stage_a(&b8).unwrap();
        tree.apply_verified_block(Arc::new(b8)).unwrap();
        assert_eq!(tree.tip_state().open_jobs.len(), 1);

        // settle_delay = 2: the job settles at h = 10.
        for h in 9..=10 {
            let b = mine_one(&tree, tree.tip_id(), 1, &[], h, 1_700_000_000 + h);
            assert_eq!(b.body.receipts.len(), usize::from(h == 10));
            tree.pre_validate(&b, None).unwrap();
            tree.apply_verified_block(Arc::new(b)).unwrap();
        }
        assert!(tree.tip_state().open_jobs.is_empty());
        assert_eq!(
            tree.tip_state().ledger.balance(StateCategory::Escrow).get(),
            0
        );
        let summaries = tree.canonical_summaries(None, 100);
        assert_eq!(summaries.len(), 10);
        assert!(
            summaries
                .iter()
                .all(|s| s.total_after == u128::from(TOTAL_SUPPLY.get()))
        );
    }

    #[test]
    fn fork_choice_heaviest_branch_and_tie_rule() {
        let g = test_genesis();
        let mut tree = BlockTree::new(g).unwrap();
        let genesis_id = tree.genesis_id();

        let a1 = mine_one(&tree, genesis_id, 1, &[], 1, 1_700_000_001);
        let b1 = mine_one(&tree, genesis_id, 2, &[], 2, 1_700_000_001);

        let out_a1 = tree.apply_verified_block(Arc::new(a1.clone())).unwrap();
        assert!(out_a1.tip_changed);
        assert_eq!(tree.tip_id(), a1.header.block_id);

        // A tie at height 1 keeps the current tip (a1).
        let out_b1 = tree.apply_verified_block(Arc::new(b1.clone())).unwrap();
        assert!(!out_b1.tip_changed);
        assert_eq!(tree.tip_id(), a1.header.block_id);

        // Extending branch B to height 2 makes it heavier: reorg.
        let b2 = mine_one(&tree, b1.header.block_id, 2, &[], 3, 1_700_000_002);
        tree.pre_validate(&b2, None).unwrap();
        let out_b2 = tree.apply_verified_block(Arc::new(b2.clone())).unwrap();
        assert!(out_b2.tip_changed);
        assert_eq!(tree.tip_id(), b2.header.block_id);
        assert_eq!(out_b2.disconnected.len(), 1);
        assert_eq!(out_b2.disconnected[0].header.block_id, a1.header.block_id);
        let connected: Vec<Digest> = out_b2.connected.iter().map(|b| b.header.block_id).collect();
        assert_eq!(connected, vec![b1.header.block_id, b2.header.block_id]);
        assert_eq!(tree.canonical_id_at(1), Some(b1.header.block_id));
        assert_eq!(tree.canonical_id_at(2), Some(b2.header.block_id));

        // A block on the abandoned branch still validates against its own ancestry.
        let a2 = mine_one(&tree, a1.header.block_id, 1, &[], 4, 1_700_000_002);
        tree.pre_validate(&a2, None).unwrap();
        let out_a2 = tree.apply_verified_block(Arc::new(a2)).unwrap();
        assert!(!out_a2.tip_changed, "equal weight keeps the current tip");
    }
}
EOF

cat << 'EOF' > chain/tests/consensus_suite.rs
//! Consensus and STF tests (§11 unit tests 3–7).

#![forbid(unsafe_code)]

use std::sync::Arc;

use chain::core_adapter::fw_context_to_core;
use chain::{
    BlockTree, StfError, TreeError, VerifiedShare, apply_body, build_template, compute_body_root,
    compute_client_digest, compute_difficulty_context, compute_job_ids,
};
use ledger::{LedgerError, StateCategory};
use primitives::{Atoms, TOTAL_SUPPLY};
use wire::{
    Block, DIGEST_LEN, DifficultyMode, Digest, FeeTransition, GenesisConfig, JobPayload,
    JobTransaction, MAX_REORG_DEPTH, ShareProof, Target,
};
use work::FreshWorkIds;

fn fast_genesis() -> GenesisConfig {
    let mut g = GenesisConfig::default_testnet(1_700_000_000);
    // Every attempt seals and every header is a share: one tile per block.
    g.initial_seal_target = Target(u128::MAX);
    g.share_ratio = 1;
    g.difficulty = DifficultyMode::Fixed;
    g.blocks_per_epoch = 5;
    g.maturation_delay = 2;
    g.settle_delay = 2;
    g.share_maturity_depth = 1;
    g.snapshot_window = 30;
    g.share_inclusion_window = 15;
    g
}

fn make_job(
    seed: u64,
    queue_fee: u64,
    base_fee: u64,
    v_exec: u64,
    expiry_height: u64,
) -> JobTransaction {
    let mut s = seed.wrapping_add(1);
    let mut next_val = || -> f64 {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        ((s % 2000) as i64 - 1000) as f64
    };
    let xs: Vec<f64> = (0..512).map(|_| next_val()).collect();
    let ys: Vec<f64> = (0..512).map(|_| next_val()).collect();
    JobTransaction {
        client: compute_client_digest("bench").unwrap(),
        queue_fee,
        base_fee,
        v_exec,
        v_da: 50_000_000,
        v_ref: 50_000_000,
        expiry_height,
        nonce: seed,
        payload: JobPayload::ExactDot { xs, ys },
    }
}

fn template_on(
    tree: &BlockTree,
    parent_id: Digest,
    owner: u64,
    mempool: &[JobTransaction],
    shares: &[ShareProof],
) -> chain::Template {
    let anc = tree.ancestor_view(parent_id).unwrap();
    let parent_meta = tree.get_meta(&parent_id).unwrap();
    let parent_state = tree.get_state(&parent_id).unwrap();
    build_template(
        1,
        tree.genesis(),
        tree.genesis_id(),
        &anc,
        parent_meta.height,
        &parent_state,
        mempool,
        shares,
        owner,
        parent_meta.time_bucket + 1,
    )
    .unwrap()
}

fn work_ids(ctx: &wire::FwContext) -> FreshWorkIds {
    let core_ctx = fw_context_to_core(ctx).unwrap();
    let inst = core_ctx.instance();
    let z = inst.x.product(&inst.y);
    FreshWorkIds::derive(&core_ctx, &z)
}

fn mine_block_on(
    tree: &BlockTree,
    parent_id: Digest,
    owner: u64,
    mempool: &[JobTransaction],
    shares: &[ShareProof],
    nonce: u64,
) -> Block {
    let tpl = template_on(tree, parent_id, owner, mempool, shares);
    tpl.seal(nonce, &work_ids(&tpl.context_with_nonce(nonce)))
}

fn mine_share_on(tree: &BlockTree, parent_id: Digest, owner: u64, nonce: u64) -> ShareProof {
    let tpl = template_on(tree, parent_id, owner, &[], &[]);
    tpl.share(nonce, &work_ids(&tpl.context_with_nonce(nonce)))
}

fn extend(tree: &mut BlockTree, block: Block) {
    tree.pre_validate(&block, None).unwrap();
    BlockTree::verify_stage_a(&block).unwrap();
    tree.apply_verified_block(Arc::new(block)).unwrap();
}

/// Unit test 3 (§11): 200 blocks with random job counts, random fees and epoch boundaries.
/// `apply_body` conserves `M = 1.5 * 10^15` atoms and passes `check_invariants()` after
/// every block.
#[test]
fn randomized_200_blocks_conserve_supply_m() {
    let g = fast_genesis();
    let (_, ledger, _) = chain::validate_genesis(&g).unwrap();
    let mut state = chain::NodeState::genesis(ledger);

    let mut rng = 0x1234_5678_9abc_def0u64;
    let mut next_u64 = || -> u64 {
        rng ^= rng << 13;
        rng ^= rng >> 7;
        rng ^= rng << 17;
        rng
    };

    let mut admitted = 0usize;
    let mut settled = 0usize;
    for h in 1..=200u64 {
        let share_owner = (next_u64() % 5) + 1;
        let mut wid = [0u8; DIGEST_LEN];
        wid[0..8].copy_from_slice(&h.to_be_bytes());
        wid[8..16].copy_from_slice(&next_u64().to_be_bytes());
        let shares = vec![VerifiedShare {
            work_id: Digest(wid),
            owner: share_owner,
            weight: 34_359_738_368,
            height: h.saturating_sub(1).max(1),
        }];

        let mut jobs = Vec::new();
        // The epoch-1 booking is paid at h = 10; from then on U has spendable rewards.
        if h >= 10 {
            let count = (next_u64() % 4) as usize;
            for j in 0..count {
                let seed = h * 100 + j as u64;
                let q_fee = ((next_u64() % 5) + 1) * 10_000_000;
                let b_fee = ((next_u64() % 10) + 1) * 100_000_000;
                let v_exec = ((next_u64() % 20) + 1) * 100_000_000;
                jobs.push(make_job(seed, q_fee, b_fee, v_exec, h + 50));
            }
            jobs.sort_by_key(|tx| compute_job_ids(tx).unwrap().0);
        }

        let (next_state, derived) = apply_body(&state, &g, h, &jobs, &shares).unwrap();
        assert_eq!(next_state.ledger.total(), u128::from(TOTAL_SUPPLY.get()));
        next_state.ledger.check_invariants().unwrap();
        for ft in &derived.fee_transitions {
            let sum: i128 = ft.delta().iter().sum();
            assert_eq!(sum, 0, "every fee transition delta must sum to zero");
        }
        assert_eq!(derived.leases.len(), jobs.len());
        admitted += jobs.len();
        settled += derived.receipts.len();
        state = next_state;
    }
    assert!(admitted > 100, "the random schedule must admit many jobs");
    assert_eq!(
        settled + state.open_jobs.len(),
        admitted,
        "every admitted job settles after settle_delay"
    );
}

/// Unit test 4 (§11): tampering with a derived field, a context field, a target,
/// `miner_owner`, an operand, or the fee-transition order is rejected.
#[test]
fn tampering_with_block_fields_is_rejected() {
    let g = fast_genesis();
    let mut tree = BlockTree::new(g).unwrap();

    // Advance to height 10, where the epoch-1 booking is paid into U.
    for h in 1..=10 {
        let blk = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], h);
        extend(&mut tree, blk);
    }

    let job = make_job(555, 100_000_000, 1_000_000_000, 8_000_000_000, 100);
    let honest = mine_block_on(&tree, tree.tip_id(), 1, &[job], &[], 11);
    assert_eq!(honest.body.jobs.len(), 1);
    assert!(honest.body.fee_transitions.len() >= 2);

    // Derived fields: rejected by apply_verified_block even with a consistent body root.
    let mut bad_digest = honest.clone();
    bad_digest.body.ledger_digest.0[0] ^= 0x01;
    bad_digest.header.context.body_core_root = compute_body_root(&bad_digest.body).unwrap();
    assert!(tree.apply_verified_block(Arc::new(bad_digest)).is_err());

    let mut bad_ft_order = honest.clone();
    bad_ft_order.body.fee_transitions.reverse();
    bad_ft_order.header.context.body_core_root = compute_body_root(&bad_ft_order.body).unwrap();
    assert!(tree.apply_verified_block(Arc::new(bad_ft_order)).is_err());

    let mut bad_leases = honest.clone();
    bad_leases.body.leases[0].owner = 999;
    bad_leases.header.context.body_core_root = compute_body_root(&bad_leases.body).unwrap();
    assert!(tree.apply_verified_block(Arc::new(bad_leases)).is_err());

    // Context field: rejected by Stage B.
    let mut bad_ctx = honest.clone();
    bad_ctx.header.context.height += 1;
    assert!(tree.pre_validate(&bad_ctx, None).is_err());

    // Targets, even with a matching difficulty context digest.
    let mut bad_target = honest.clone();
    bad_target.header.seal_target = Target(u128::MAX - 1);
    bad_target.header.context.parent_derived_difficulty_context = compute_difficulty_context(
        bad_target.header.seal_target,
        bad_target.header.share_target,
    );
    assert!(tree.pre_validate(&bad_target, None).is_err());

    let mut bad_owner = honest.clone();
    bad_owner.header.miner_owner = 2;
    assert!(tree.pre_validate(&bad_owner, None).is_err());

    // One operand changed without updating body_core_root.
    let mut bad_operand = honest.clone();
    let JobPayload::ExactDot { ref mut xs, .. } = bad_operand.body.jobs[0].payload;
    xs[0] += 1.0;
    assert!(tree.pre_validate(&bad_operand, None).is_err());

    // Stage A: a forged nonce no longer matches the claimed work.
    let mut bad_nonce = honest.clone();
    bad_nonce.header.context.attempt_nonce += 1;
    assert!(BlockTree::verify_stage_a(&bad_nonce).is_err());

    // The honest block still applies.
    extend(&mut tree, honest);
    assert_eq!(tree.tip_meta().height, 11);
}

/// Unit test 5 (§11): job flow, `FounderTrancheLocked`, and `R_l -> R_a` as two lots.
#[test]
fn job_fee_lock_and_two_lot_maturation_flow() {
    let g = fast_genesis(); // blocks_per_epoch = 5, maturation_delay = 2, settle_delay = 2
    let mut tree = BlockTree::new(g.clone()).unwrap();
    let job = make_job(999, 100_000_000, 1_000_000_000, 8_000_000_000, 100);

    // Funding before any reward reached U fails on the locked founder tranches.
    let sh = VerifiedShare {
        work_id: Digest([1u8; DIGEST_LEN]),
        owner: 1,
        weight: 100,
        height: 1,
    };
    let (s1, _) = apply_body(&tree.tip_state(), &g, 1, &[], &[sh]).unwrap();
    let res = apply_body(&s1, &g, 2, std::slice::from_ref(&job), &[]);
    assert!(matches!(
        res,
        Err(StfError::Ledger(LedgerError::FounderTrancheLocked { .. }))
    ));

    // Blocks 1..=9: the job stays out of the template.
    for h in 1..=9 {
        let blk = mine_block_on(&tree, tree.tip_id(), 1, std::slice::from_ref(&job), &[], h);
        assert!(blk.body.jobs.is_empty(), "h = {h}");
        extend(&mut tree, blk);
    }

    // h = 10 (epoch 2): the epoch-1 booking is paid into U and the job is admitted;
    // R_l holds queue_fee + base_fee = 1.1 * 10^9 atoms as two locked fees.
    let b10 = mine_block_on(&tree, tree.tip_id(), 1, std::slice::from_ref(&job), &[], 10);
    assert_eq!(b10.body.jobs.len(), 1);
    assert!(matches!(
        b10.body.fee_transitions[1],
        FeeTransition::FwReward { amount, .. } if amount > 0
    ));
    extend(&mut tree, b10);
    let ledger = &tree.tip_state().ledger;
    assert_eq!(
        ledger.balance(StateCategory::LockedBaseFees),
        Atoms(1_100_000_000)
    );
    // After admission the escrow holds exactly v_exec + v_da + v_ref.
    assert_eq!(ledger.balance(StateCategory::Escrow), Atoms(8_100_000_000));
    assert_eq!(ledger.locked_fees().len(), 2);

    // Paid in epoch 2 with L = 2: maturity epoch 2 + 2 + 1 = 5, i.e. h = 25.
    for h in 11..=25 {
        let blk = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], h);
        assert_eq!(blk.body.receipts.len(), usize::from(h == 12), "h = {h}");
        if h == 25 {
            let mat = blk
                .body
                .fee_transitions
                .iter()
                .find_map(|ft| match ft {
                    FeeTransition::ReserveMature { matured_lots, .. } => Some(matured_lots.clone()),
                    _ => None,
                })
                .unwrap();
            assert_eq!(
                mat.len(),
                2,
                "queue_fee and base_fee mature as 2 independent lots"
            );
        }
        extend(&mut tree, blk);
    }

    let ledger = &tree.tip_state().ledger;
    assert_eq!(ledger.balance(StateCategory::LockedBaseFees), Atoms::ZERO);
    assert_eq!(ledger.balance(StateCategory::Escrow), Atoms::ZERO);
    assert_eq!(
        ledger.fee_lots().len(),
        3,
        "Genesis lot + 2 matured fee lots"
    );
}

/// Unit tests 6 and 7 (§11): share inclusion rules and `MAX_REORG_DEPTH`.
#[test]
fn share_validation_rules_and_max_reorg_depth() {
    let mut g = fast_genesis();
    g.share_inclusion_window = 3;
    let mut tree = BlockTree::new(g).unwrap();

    for h in 1..=5 {
        let blk = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], h);
        extend(&mut tree, blk);
    }

    // A share mined at height 1 is outside the window (3) at height 6.
    let p0 = tree.canonical_id_at(0).unwrap();
    let old_share = mine_share_on(&tree, p0, 2, 77);
    assert_eq!(old_share.context.height, 1);
    let mut blk_with_old = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], 6);
    blk_with_old.body.shares.push(old_share);
    blk_with_old.header.context.body_core_root = compute_body_root(&blk_with_old.body).unwrap();
    assert!(tree.pre_validate(&blk_with_old, None).is_err());

    // A valid share mined at height 5 on the canonical parent.
    let p4 = tree.canonical_id_at(4).unwrap();
    let valid_share = mine_share_on(&tree, p4, 2, 88);
    assert_eq!(valid_share.context.height, 5);

    // Wrong owner digest.
    let mut bad_owner_share = valid_share.clone();
    bad_owner_share.owner = 99;
    let mut blk_bad_owner = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], 6);
    blk_bad_owner.body.shares.push(bad_owner_share);
    blk_bad_owner.header.context.body_core_root = compute_body_root(&blk_bad_owner.body).unwrap();
    assert!(tree.pre_validate(&blk_bad_owner, None).is_err());

    // Wrong share target.
    let mut bad_target_share = valid_share.clone();
    bad_target_share.share_target = Target(u128::MAX - 10);
    let mut blk_bad_target = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], 6);
    blk_bad_target.body.shares.push(bad_target_share);
    blk_bad_target.header.context.body_core_root = compute_body_root(&blk_bad_target.body).unwrap();
    assert!(tree.pre_validate(&blk_bad_target, None).is_err());

    // The valid share goes through the template and registers with its owner.
    let with_share = mine_block_on(
        &tree,
        tree.tip_id(),
        1,
        &[],
        std::slice::from_ref(&valid_share),
        6,
    );
    assert_eq!(with_share.body.shares, vec![valid_share.clone()]);
    extend(&mut tree, with_share);
    assert_eq!(
        tree.tip_state().shares[&valid_share.work_id].owner,
        2,
        "share registered for its owner"
    );

    // Advance past MAX_REORG_DEPTH and check that a fork from genesis is TooDeep.
    for h in 7..=MAX_REORG_DEPTH + 6 {
        let blk = mine_block_on(&tree, tree.tip_id(), 1, &[], &[], h);
        tree.pre_validate(&blk, None).unwrap();
        tree.apply_verified_block(Arc::new(blk)).unwrap();
    }
    let deep_fork_blk = mine_block_on(&tree, tree.genesis_id(), 2, &[], &[], 999);
    assert_eq!(
        tree.pre_validate(&deep_fork_blk, None),
        Err(TreeError::TooDeep)
    );
}
