cat << 'EOF' > node/src/mempool.rs
//! Mempool actor (`node::mempool`, §8.4).

use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::Arc;

use chain::{JobValidationError, compute_job_ids, validate_job_stateless};
use tokio::sync::{broadcast, mpsc, oneshot, watch};
use tracing::warn;
use wire::{Block, Digest, JobTransaction, MEMPOOL_CAPACITY};

use crate::chain_actor::{ChainCmd, ChainEvent, Origin, StatusSnapshot};

/// FIFO snapshot of pooled transactions, published to the ChainState actor for templates.
#[derive(Clone, Debug, Default)]
pub struct MempoolView {
    /// Oldest first, at most `4 * max_jobs_per_block` entries.
    pub txs: Vec<JobTransaction>,
    /// Total number of pooled transactions.
    pub size: usize,
}

/// Event broadcast by `MempoolActor` when a job is accepted.
#[derive(Clone, Debug)]
pub enum MempoolEvent {
    /// A new job entered the pool (relayed to peers except `origin`).
    Accepted {
        /// The job.
        tx: JobTransaction,
        /// Where it came from.
        origin: Origin,
    },
}

/// Successful insertion receipt returned to RPC and P2P callers.
#[derive(Clone, Debug)]
pub struct MempoolInsertOk {
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Job identifier.
    pub job_id: u64,
    /// Escrow deposit `D`.
    pub deposit: u64,
    /// `D + f_queue`.
    pub total_charge: u64,
    /// Exact dot product the job will settle with.
    pub expected_result: i128,
}

/// Rejection reasons of `MempoolCmd::Insert`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MempoolReject {
    /// Same `tx_id` or `job_id` already pooled.
    Duplicate,
    /// The pool holds `MEMPOOL_CAPACITY` transactions (no fee-based eviction).
    Full,
    /// The transaction is invalid.
    Invalid {
        /// Stable error code for the RPC (§9.5).
        code: &'static str,
        /// Human-readable reason.
        message: String,
    },
}

/// Commands accepted by `MempoolActor`.
pub enum MempoolCmd {
    /// Validates and pools a job.
    Insert {
        /// The job.
        tx: JobTransaction,
        /// Where it came from.
        origin: Origin,
        /// Outcome.
        reply: oneshot::Sender<Result<MempoolInsertOk, MempoolReject>>,
    },
    /// Number of pooled transactions.
    Stats {
        /// Pool size.
        reply: oneshot::Sender<usize>,
    },
    /// The oldest `limit` pooled transactions.
    List {
        /// Maximum entries.
        limit: usize,
        /// Transactions, oldest first.
        reply: oneshot::Sender<Vec<JobTransaction>>,
    },
}

struct PooledEntry {
    tx_id: Digest,
    job_id: u64,
    tx: JobTransaction,
}

/// Asynchronous mempool actor (§8.4).
pub struct MempoolActor {
    cmd_rx: mpsc::Receiver<MempoolCmd>,
    chain_tx: mpsc::Sender<ChainCmd>,
    chain_events: broadcast::Receiver<ChainEvent>,
    event_tx: broadcast::Sender<MempoolEvent>,
    view_tx: watch::Sender<Arc<MempoolView>>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    fifo: VecDeque<PooledEntry>,
    by_tx_id: HashSet<Digest>,
    by_job_id: HashMap<u64, Digest>,
}

fn rejection_code(err: &JobValidationError) -> &'static str {
    match err {
        JobValidationError::ZeroFee(_) => "zero_fee",
        JobValidationError::AmountOverflow => "amount_overflow",
        JobValidationError::TooLarge(_) => "too_large",
        JobValidationError::InvalidPayload(_) => "invalid_payload",
    }
}

impl MempoolActor {
    /// Creates the actor; call [`MempoolActor::run`] to start it.
    pub fn new(
        cmd_rx: mpsc::Receiver<MempoolCmd>,
        chain_tx: mpsc::Sender<ChainCmd>,
        chain_events: broadcast::Receiver<ChainEvent>,
        event_tx: broadcast::Sender<MempoolEvent>,
        view_tx: watch::Sender<Arc<MempoolView>>,
        status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    ) -> Self {
        Self {
            cmd_rx,
            chain_tx,
            chain_events,
            event_tx,
            view_tx,
            status_rx,
            fifo: VecDeque::new(),
            by_tx_id: HashSet::new(),
            by_job_id: HashMap::new(),
        }
    }

    /// Runs until `shutdown` turns true (or its sender is dropped).
    pub async fn run(mut self, mut shutdown: watch::Receiver<bool>) {
        loop {
            tokio::select! {
                res = shutdown.changed() => {
                    if res.is_err() || *shutdown.borrow() {
                        break;
                    }
                }
                Some(cmd) = self.cmd_rx.recv() => self.handle_cmd(cmd),
                ev = self.chain_events.recv() => match ev {
                    Ok(ChainEvent::TipChanged { tip, connected, disconnected }) => {
                        self.handle_tip_changed(tip.height, &connected, &disconnected);
                    }
                    Ok(_) => {}
                    Err(broadcast::error::RecvError::Lagged(skipped)) => {
                        warn!(skipped, "Mempool lagged behind chain events; asking ChainState");
                        self.recover_from_lag().await;
                    }
                    Err(broadcast::error::RecvError::Closed) => break,
                },
            }
        }
    }

    fn handle_cmd(&mut self, cmd: MempoolCmd) {
        match cmd {
            MempoolCmd::Insert { tx, origin, reply } => {
                let _ = reply.send(self.insert_tx(tx, origin));
            }
            MempoolCmd::Stats { reply } => {
                let _ = reply.send(self.fifo.len());
            }
            MempoolCmd::List { limit, reply } => {
                let _ = reply.send(self.fifo.iter().take(limit).map(|e| e.tx.clone()).collect());
            }
        }
    }

    fn next_height(&self) -> u64 {
        self.status_rx.borrow().tip.height + 1
    }

    fn insert_tx(
        &mut self,
        tx: JobTransaction,
        origin: Origin,
    ) -> Result<MempoolInsertOk, MempoolReject> {
        let (tx_id, job_id, deposit, expected_result) =
            validate_job_stateless(&tx).map_err(|err| MempoolReject::Invalid {
                code: rejection_code(&err),
                message: err.to_string(),
            })?;
        let total_charge = tx
            .checked_total_charge()
            .ok_or_else(|| MempoolReject::Invalid {
                code: "amount_overflow",
                message: "total charge overflow".to_string(),
            })?;
        let next_height = self.next_height();
        if tx.expiry_height < next_height {
            return Err(MempoolReject::Invalid {
                code: "bad_request",
                message: format!(
                    "job expiry_height {} < next block height {next_height}",
                    tx.expiry_height
                ),
            });
        }
        if self.by_tx_id.contains(&tx_id) || self.by_job_id.contains_key(&job_id) {
            return Err(MempoolReject::Duplicate);
        }
        if self.fifo.len() >= MEMPOOL_CAPACITY {
            return Err(MempoolReject::Full);
        }

        self.push(tx_id, job_id, tx.clone());
        self.publish_view();
        let _ = self.event_tx.send(MempoolEvent::Accepted { tx, origin });
        Ok(MempoolInsertOk {
            tx_id,
            job_id,
            deposit,
            total_charge,
            expected_result,
        })
    }

    fn push(&mut self, tx_id: Digest, job_id: u64, tx: JobTransaction) {
        self.by_tx_id.insert(tx_id);
        self.by_job_id.insert(job_id, tx_id);
        self.fifo.push_back(PooledEntry { tx_id, job_id, tx });
    }

    fn handle_tip_changed(
        &mut self,
        tip_height: u64,
        connected: &[Arc<Block>],
        disconnected: &[Arc<Block>],
    ) {
        let connected_txs: HashSet<Digest> = connected
            .iter()
            .flat_map(|blk| &blk.body.jobs)
            .filter_map(|tx| compute_job_ids(tx).ok().map(|(id, _)| id))
            .collect();
        let next_height = tip_height + 1;

        // Remove txs included by the new branch, and txs that expired.
        self.remove_where(|e| connected_txs.contains(&e.tx_id) || e.tx.expiry_height < next_height);

        // Return the txs of the abandoned branch (already validated statelessly).
        for tx in disconnected.iter().flat_map(|blk| &blk.body.jobs) {
            if tx.expiry_height < next_height || self.fifo.len() >= MEMPOOL_CAPACITY {
                continue;
            }
            let Ok((tx_id, job_id)) = compute_job_ids(tx) else {
                continue;
            };
            if connected_txs.contains(&tx_id)
                || self.by_tx_id.contains(&tx_id)
                || self.by_job_id.contains_key(&job_id)
            {
                continue;
            }
            self.push(tx_id, job_id, tx.clone());
        }
        self.publish_view();
    }

    async fn recover_from_lag(&mut self) {
        let tx_ids: Vec<Digest> = self.by_tx_id.iter().copied().collect();
        let (reply_tx, reply_rx) = oneshot::channel();
        let request = ChainCmd::FilterIncluded {
            tx_ids,
            reply: reply_tx,
        };
        if self.chain_tx.send(request).await.is_err() {
            return;
        }
        let Ok(included) = reply_rx.await else {
            return;
        };
        let included: HashSet<Digest> = included.into_iter().collect();
        let next_height = self.next_height();
        self.remove_where(|e| included.contains(&e.tx_id) || e.tx.expiry_height < next_height);
        self.publish_view();
    }

    fn remove_where(&mut self, pred: impl Fn(&PooledEntry) -> bool) {
        let (by_tx_id, by_job_id) = (&mut self.by_tx_id, &mut self.by_job_id);
        self.fifo.retain(|entry| {
            let remove = pred(entry);
            if remove {
                by_tx_id.remove(&entry.tx_id);
                by_job_id.remove(&entry.job_id);
            }
            !remove
        });
    }

    fn publish_view(&self) {
        let max_jobs = usize::try_from(self.status_rx.borrow().max_jobs_per_block).unwrap_or(32);
        let cap = max_jobs.saturating_mul(4).max(32);
        let txs = self.fifo.iter().take(cap).map(|e| e.tx.clone()).collect();
        let _ = self.view_tx.send(Arc::new(MempoolView {
            txs,
            size: self.fifo.len(),
        }));
    }
}
EOF

cat << 'EOF' > node/src/net.rs
//! P2P network manager: length-delimited TCP framing, handshake, gossip relay, sync
//! driver and misbehaviour bans (`node::net`, §4, §8.6).

use std::collections::{HashMap, HashSet, VecDeque};
use std::net::{IpAddr, SocketAddr};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::{Duration, Instant};

use bytes::Bytes;
use futures::{SinkExt, StreamExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{broadcast, mpsc, oneshot, watch};
use tokio::time::Instant as TokioInstant;
use tokio_util::codec::{Framed, LengthDelimitedCodec};
use tracing::{debug, info, warn};
use wire::{
    Block, Digest, HANDSHAKE_TIMEOUT, MAX_FRAME_BYTES, MAX_REORG_DEPTH, MAX_SYNC_BLOCKS,
    MAX_SYNC_BYTES, SYNC_LOOKBACK, SYNC_TIMEOUT, WIRE_VERSION, WireMessage, codec,
};

use crate::chain_actor::{ChainCmd, ChainEvent, ImportAck, Origin, PeerId, StatusSnapshot};
use crate::mempool::{MempoolCmd, MempoolEvent, MempoolReject};

/// Ban for protocol violations (bad frames, unexpected messages), §4.8.
const PROTOCOL_BAN: Duration = Duration::from_secs(60);
/// Ban for invalid blocks or repeated invalid jobs, §4.8.
const INVALID_BAN: Duration = Duration::from_secs(600);
/// Invalid jobs tolerated per connection before a ban.
const MAX_INVALID_JOBS: u32 = 10;
/// Accepted blocks more than this far below the tip are not relayed: peers that
/// need them fetch them with `SyncRequest`.
const RELAY_DEPTH: u64 = 2 * SYNC_LOOKBACK;

/// What a ban applies to. Loopback peers are banned by full socket address, so one
/// misbehaving local node cannot lock every other local node out of a localhost testnet.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum BanKey {
    Ip(IpAddr),
    Addr(SocketAddr),
}

fn ban_key(addr: SocketAddr) -> BanKey {
    if addr.ip().is_loopback() {
        BanKey::Addr(addr)
    } else {
        BanKey::Ip(addr.ip())
    }
}

struct PeerHandle {
    addr: SocketAddr,
    outbound: bool,
    tx: mpsc::Sender<WireMessage>,
    best_height: u64,
    invalid_jobs: u32,
}

#[derive(Default)]
struct SyncState {
    from: u64,
    lookback: u64,
    /// A `SyncRequest` is outstanding.
    outstanding: bool,
    deadline: Option<TokioInstant>,
    /// Last block of the previous batch: the next request waits until it is applied.
    awaiting: Option<(Digest, u64)>,
}

struct LruSeen<T> {
    order: VecDeque<T>,
    set: HashSet<T>,
    capacity: usize,
}

impl<T: Copy + Eq + std::hash::Hash> LruSeen<T> {
    fn new(capacity: usize) -> Self {
        Self {
            order: VecDeque::with_capacity(capacity),
            set: HashSet::with_capacity(capacity),
            capacity,
        }
    }

    /// Records `item`; returns false if it was already seen.
    fn mark_seen(&mut self, item: T) -> bool {
        if !self.set.insert(item) {
            return false;
        }
        if self.order.len() >= self.capacity
            && let Some(old) = self.order.pop_front()
        {
            self.set.remove(&old);
        }
        self.order.push_back(item);
        true
    }
}

struct NetShared {
    peers: HashMap<PeerId, PeerHandle>,
    bans: HashMap<BanKey, Instant>,
    seen_blocks: LruSeen<Digest>,
    seen_jobs: LruSeen<Digest>,
    paused: bool,
}

/// Why a connection loop ended.
enum Disconnect {
    Closed,
    Ban(Duration, String),
}

/// Manages TCP peers, gossip relay, sync and misbehaviour bans (§4, §8.6).
pub struct PeerManager {
    local_addr: SocketAddr,
    chain_id: u64,
    next_peer_id: AtomicU64,
    shared: Mutex<NetShared>,
    chain_tx: mpsc::Sender<ChainCmd>,
    mempool_tx: mpsc::Sender<MempoolCmd>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    shutdown_rx: watch::Receiver<bool>,
}

fn is_shutdown(rx: &watch::Receiver<bool>) -> bool {
    *rx.borrow()
}

async fn wait_shutdown(rx: &mut watch::Receiver<bool>) {
    while !*rx.borrow() {
        if rx.changed().await.is_err() {
            return;
        }
    }
}

impl PeerManager {
    /// Binds the listener and starts the accept loop, the dialers and the relay loop.
    #[allow(clippy::too_many_arguments)]
    pub async fn start(
        listen_addr: SocketAddr,
        static_peers: Vec<SocketAddr>,
        chain_id: u64,
        chain_tx: mpsc::Sender<ChainCmd>,
        mempool_tx: mpsc::Sender<MempoolCmd>,
        mut chain_events: broadcast::Receiver<ChainEvent>,
        mut mempool_events: broadcast::Receiver<MempoolEvent>,
        status_rx: watch::Receiver<Arc<StatusSnapshot>>,
        shutdown_rx: watch::Receiver<bool>,
    ) -> std::io::Result<Arc<Self>> {
        let listener = TcpListener::bind(listen_addr).await?;
        let local_addr = listener.local_addr()?;
        let manager = Arc::new(Self {
            local_addr,
            chain_id,
            next_peer_id: AtomicU64::new(1),
            shared: Mutex::new(NetShared {
                peers: HashMap::new(),
                bans: HashMap::new(),
                seen_blocks: LruSeen::new(8_192),
                seen_jobs: LruSeen::new(16_384),
                paused: false,
            }),
            chain_tx,
            mempool_tx,
            status_rx,
            shutdown_rx: shutdown_rx.clone(),
        });

        // Accept loop
        let mgr = manager.clone();
        let mut sd = shutdown_rx.clone();
        tokio::spawn(async move {
            loop {
                tokio::select! {
                    () = wait_shutdown(&mut sd) => break,
                    accepted = listener.accept() => {
                        let Ok((stream, addr)) = accepted else { continue };
                        if mgr.is_banned_or_paused(addr) {
                            continue;
                        }
                        let conn = mgr.clone();
                        tokio::spawn(async move { conn.run_connection(stream, addr, false).await });
                    }
                }
            }
        });

        // Outbound dialers with exponential backoff (§4.5)
        for peer_addr in static_peers {
            manager.spawn_dialer(peer_addr);
        }

        // Relay loop (§4.6, §8.6)
        let mgr = manager.clone();
        let mut sd = shutdown_rx;
        tokio::spawn(async move {
            loop {
                tokio::select! {
                    () = wait_shutdown(&mut sd) => break,
                    ev = chain_events.recv() => match ev {
                        Ok(ev) => mgr.handle_chain_event(ev),
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            warn!(skipped = n, "Relay loop lagged behind chain events");
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                    },
                    ev = mempool_events.recv() => match ev {
                        Ok(ev) => mgr.handle_mempool_event(ev),
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            warn!(skipped = n, "Relay loop lagged behind mempool events");
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                    },
                }
            }
        });

        Ok(manager)
    }

    /// Bound listen address.
    pub fn local_addr(&self) -> SocketAddr {
        self.local_addr
    }

    /// Number of connected peers.
    pub fn peer_count(&self) -> usize {
        self.lock().peers.len()
    }

    /// Adds an outbound peer with its own reconnecting dialer.
    pub fn add_outbound_peer(self: &Arc<Self>, addr: SocketAddr) {
        self.spawn_dialer(addr);
    }

    /// Pauses (drops every connection, refuses new ones) or resumes networking.
    /// Used to partition nodes in tests.
    pub fn set_network_paused(&self, paused: bool) {
        let mut guard = self.lock();
        guard.paused = paused;
        if paused {
            guard.peers.clear();
        }
    }

    fn lock(&self) -> MutexGuard<'_, NetShared> {
        self.shared.lock().unwrap_or_else(|e| e.into_inner())
    }

    fn spawn_dialer(self: &Arc<Self>, peer_addr: SocketAddr) {
        if peer_addr == self.local_addr {
            return;
        }
        let mgr = self.clone();
        let mut sd = self.shutdown_rx.clone();
        tokio::spawn(async move {
            let mut backoff_secs = 1u64;
            while !is_shutdown(&sd) {
                if !mgr.has_peer_addr(peer_addr) && !mgr.is_banned_or_paused(peer_addr) {
                    match TcpStream::connect(peer_addr).await {
                        Ok(stream) => {
                            backoff_secs = 1;
                            mgr.run_connection(stream, peer_addr, true).await;
                        }
                        Err(_) => backoff_secs = (backoff_secs * 2).min(30),
                    }
                }
                tokio::select! {
                    () = tokio::time::sleep(Duration::from_secs(backoff_secs)) => {}
                    () = wait_shutdown(&mut sd) => break,
                }
            }
        });
    }

    fn is_banned_or_paused(&self, addr: SocketAddr) -> bool {
        let mut guard = self.lock();
        if guard.paused {
            return true;
        }
        let now = Instant::now();
        guard.bans.retain(|_, until| now < *until);
        guard.bans.contains_key(&ban_key(addr)) || guard.bans.contains_key(&BanKey::Addr(addr))
    }

    fn ban(&self, addr: SocketAddr, duration: Duration, reason: &str) {
        warn!(%addr, secs = duration.as_secs(), reason, "Banning peer");
        self.lock()
            .bans
            .insert(ban_key(addr), Instant::now() + duration);
    }

    fn has_peer_addr(&self, addr: SocketAddr) -> bool {
        self.lock().peers.values().any(|p| p.addr == addr)
    }

    fn peer_best_height(&self, peer_id: PeerId) -> u64 {
        self.lock().peers.get(&peer_id).map_or(0, |p| p.best_height)
    }

    fn broadcast(&self, msg: &WireMessage, exclude: Option<PeerId>) {
        let guard = self.lock();
        for (&pid, handle) in &guard.peers {
            if Some(pid) != exclude {
                // A full queue drops gossip frames for that peer (§4.5).
                if handle.tx.try_send(msg.clone()).is_err() {
                    debug!(peer = pid, "Peer queue full; dropping gossip frame");
                }
            }
        }
    }

    fn handle_chain_event(&self, ev: ChainEvent) {
        match ev {
            ChainEvent::BlockAccepted { block, origin } => {
                let exclude = match origin {
                    Origin::Peer(pid) => Some(pid),
                    _ => None,
                };
                let tip_height = self.status_rx.borrow().tip.height;
                let height = block.header.context.height;
                self.lock().seen_blocks.mark_seen(block.header.block_id);
                if height + RELAY_DEPTH >= tip_height {
                    let msg = WireMessage::GossipBlock(Box::new((*block).clone()));
                    self.broadcast(&msg, exclude);
                }
            }
            ChainEvent::BlockRejected {
                block_id,
                origin: Origin::Peer(pid),
                reason,
            } => {
                let addr = self.lock().peers.remove(&pid).map(|p| p.addr);
                if let Some(addr) = addr {
                    warn!(peer = pid, id = ?block_id, %reason, "Peer sent an invalid block");
                    self.ban(addr, INVALID_BAN, &reason);
                }
            }
            _ => {}
        }
    }

    fn handle_mempool_event(&self, ev: MempoolEvent) {
        let MempoolEvent::Accepted { tx, origin } = ev;
        let exclude = match origin {
            Origin::Peer(pid) => Some(pid),
            _ => None,
        };
        if let Ok((tx_id, _)) = chain::compute_job_ids(&tx) {
            self.lock().seen_jobs.mark_seen(tx_id);
        }
        self.broadcast(&WireMessage::GossipJob(tx), exclude);
    }

    async fn run_connection(&self, stream: TcpStream, addr: SocketAddr, outbound: bool) {
        let _ = stream.set_nodelay(true);
        let codec = LengthDelimitedCodec::builder()
            .length_field_type::<u32>()
            .big_endian()
            .max_frame_length(MAX_FRAME_BYTES)
            .new_codec();
        let mut framed = Framed::new(stream, codec);

        // Send our Handshake immediately (§4.5 step 2).
        let our_hs = {
            let snap = self.status_rx.borrow();
            WireMessage::Handshake {
                version: WIRE_VERSION,
                chain_id: self.chain_id,
                best_height: snap.tip.height,
                best_block_id: snap.tip.id,
            }
        };
        let Ok(hs_bytes) = codec::encode(&our_hs) else {
            return;
        };
        if framed.send(Bytes::from(hs_bytes)).await.is_err() {
            return;
        }

        // Wait at most HANDSHAKE_TIMEOUT for the peer's Handshake (§4.5 step 3).
        // A timeout or closed socket is not misbehaviour; a wrong first frame is.
        let (peer_best_height, peer_best_id) = match tokio::time::timeout(
            HANDSHAKE_TIMEOUT,
            framed.next(),
        )
        .await
        {
            Ok(Some(Ok(bytes))) => match codec::decode::<WireMessage>(&bytes) {
                Ok(WireMessage::Handshake {
                    version,
                    chain_id,
                    best_height,
                    best_block_id,
                }) => {
                    if version != WIRE_VERSION || chain_id != self.chain_id {
                        debug!(%addr, version, chain_id, "Handshake version or chain_id mismatch");
                        return;
                    }
                    (best_height, best_block_id)
                }
                _ => {
                    self.ban(addr, PROTOCOL_BAN, "first frame is not a valid Handshake");
                    return;
                }
            },
            Ok(Some(Err(e))) if e.kind() == std::io::ErrorKind::InvalidData => {
                self.ban(addr, PROTOCOL_BAN, "oversize frame");
                return;
            }
            _ => {
                debug!(%addr, "No handshake from peer");
                return;
            }
        };

        // Register the peer, deduplicating outbound connections by address (§4.5 step 4).
        let peer_id = self.next_peer_id.fetch_add(1, Ordering::Relaxed);
        let (write_tx, mut write_rx) = mpsc::channel::<WireMessage>(256);
        {
            let mut guard = self.lock();
            if guard.paused
                || (outbound && guard.peers.values().any(|p| p.outbound && p.addr == addr))
            {
                return;
            }
            guard.peers.insert(
                peer_id,
                PeerHandle {
                    addr,
                    outbound,
                    tx: write_tx.clone(),
                    best_height: peer_best_height,
                    invalid_jobs: 0,
                },
            );
        }
        info!(peer = peer_id, %addr, outbound, peer_best_height, "Connected peer");

        let (mut sink, mut frames) = framed.split();
        let write_task = tokio::spawn(async move {
            while let Some(msg) = write_rx.recv().await {
                let Ok(bytes) = codec::encode(&msg) else {
                    break;
                };
                if sink.send(Bytes::from(bytes)).await.is_err() {
                    break;
                }
            }
        });

        let mut sync = SyncState::default();
        if peer_best_height > 0 && !self.has_block(peer_best_id).await {
            self.start_sync(&write_tx, &mut sync, peer_best_height);
        }

        let mut poll = tokio::time::interval(Duration::from_millis(100));
        let mut shutdown = self.shutdown_rx.clone();
        let mut req_window = Instant::now();
        let mut req_count = 0u32;
        let reason = loop {
            let deadline = sync.deadline;
            tokio::select! {
                () = wait_shutdown(&mut shutdown) => break Disconnect::Closed,
                frame = frames.next() => {
                    let bytes = match frame {
                        None => break Disconnect::Closed,
                        Some(Err(e)) if e.kind() == std::io::ErrorKind::InvalidData => {
                            break Disconnect::Ban(PROTOCOL_BAN, "oversize frame".into());
                        }
                        // Resets and other I/O errors are not misbehaviour.
                        Some(Err(_)) => break Disconnect::Closed,
                        Some(Ok(bytes)) => bytes,
                    };
                    let Ok(msg) = codec::decode::<WireMessage>(&bytes) else {
                        break Disconnect::Ban(PROTOCOL_BAN, "undecodable frame".into());
                    };
                    if req_window.elapsed() >= Duration::from_secs(1) {
                        req_window = Instant::now();
                        req_count = 0;
                    }
                    if matches!(msg, WireMessage::SyncRequest { .. }) {
                        req_count += 1;
                        if req_count > 10 {
                            continue; // rate limit (§4.8): drop the excess requests
                        }
                    }
                    if let Err(d) = self.handle_peer_message(peer_id, msg, &write_tx, &mut sync).await {
                        break d;
                    }
                }
                () = async {
                    match deadline {
                        Some(d) => tokio::time::sleep_until(d).await,
                        None => std::future::pending().await,
                    }
                } => {
                    debug!(peer = peer_id, "Sync request timed out");
                    sync = SyncState::default();
                }
                _ = poll.tick() => {
                    if self.lock().paused {
                        break Disconnect::Closed;
                    }
                    if let Some((await_id, last_h)) = sync.awaiting
                        && self.has_block(await_id).await
                    {
                        sync.awaiting = None;
                        sync.from = last_h + 1;
                        self.send_sync_request(&write_tx, &mut sync);
                    }
                }
            }
        };

        write_task.abort();
        self.lock().peers.remove(&peer_id);
        match reason {
            Disconnect::Closed => debug!(peer = peer_id, %addr, "Disconnected peer"),
            Disconnect::Ban(duration, why) => self.ban(addr, duration, &why),
        }
    }

    async fn handle_peer_message(
        &self,
        peer_id: PeerId,
        msg: WireMessage,
        write_tx: &mpsc::Sender<WireMessage>,
        sync: &mut SyncState,
    ) -> Result<(), Disconnect> {
        match msg {
            WireMessage::Handshake { .. } => {
                Err(Disconnect::Ban(PROTOCOL_BAN, "second Handshake".into()))
            }
            WireMessage::GossipBlock(block) => {
                let block_id = block.header.block_id;
                let height = block.header.context.height;
                {
                    let mut guard = self.lock();
                    if let Some(p) = guard.peers.get_mut(&peer_id) {
                        p.best_height = p.best_height.max(height);
                    }
                    if !guard.seen_blocks.mark_seen(block_id) {
                        return Ok(());
                    }
                }
                match self.import_block(Arc::new(*block), peer_id).await {
                    ImportAck::Orphan if height == 1 => {
                        warn!(peer = peer_id, "genesis mismatch at height 1");
                        Err(Disconnect::Closed)
                    }
                    ImportAck::Orphan => {
                        if !sync.outstanding && sync.awaiting.is_none() {
                            self.start_sync(write_tx, sync, height);
                        }
                        Ok(())
                    }
                    ImportAck::Invalid(reason) => Err(Disconnect::Ban(INVALID_BAN, reason)),
                    _ => Ok(()),
                }
            }
            WireMessage::GossipJob(tx) => {
                let Ok((tx_id, _)) = chain::compute_job_ids(&tx) else {
                    return Ok(());
                };
                if !self.lock().seen_jobs.mark_seen(tx_id) {
                    return Ok(());
                }
                let (reply_tx, reply_rx) = oneshot::channel();
                let cmd = MempoolCmd::Insert {
                    tx,
                    origin: Origin::Peer(peer_id),
                    reply: reply_tx,
                };
                if self.mempool_tx.send(cmd).await.is_err() {
                    return Ok(());
                }
                if let Ok(Err(MempoolReject::Invalid { message, .. })) = reply_rx.await {
                    let mut guard = self.lock();
                    if let Some(p) = guard.peers.get_mut(&peer_id) {
                        p.invalid_jobs += 1;
                        if p.invalid_jobs >= MAX_INVALID_JOBS {
                            return Err(Disconnect::Ban(INVALID_BAN, message));
                        }
                    }
                }
                Ok(())
            }
            WireMessage::SyncRequest { from_height } => {
                let (reply_tx, reply_rx) = oneshot::channel();
                let cmd = ChainCmd::GetCanonicalRange {
                    from_height,
                    reply: reply_tx,
                };
                let blocks = if self.chain_tx.send(cmd).await.is_ok() {
                    reply_rx.await.unwrap_or_default()
                } else {
                    Vec::new()
                };
                let blocks = blocks.into_iter().map(|b| (*b).clone()).collect();
                // SyncResponse frames are never dropped (§4.5).
                let _ = write_tx.send(WireMessage::SyncResponse { blocks }).await;
                Ok(())
            }
            WireMessage::SyncResponse { blocks } => {
                self.handle_sync_response(peer_id, blocks, write_tx, sync)
                    .await
            }
        }
    }

    async fn handle_sync_response(
        &self,
        peer_id: PeerId,
        blocks: Vec<Block>,
        write_tx: &mpsc::Sender<WireMessage>,
        sync: &mut SyncState,
    ) -> Result<(), Disconnect> {
        if !sync.outstanding {
            // Late answer to a request that already timed out: ignore it.
            debug!(peer = peer_id, "Ignoring unexpected SyncResponse");
            return Ok(());
        }
        sync.outstanding = false;
        sync.deadline = None;
        let (Some(first), Some(last)) = (blocks.first(), blocks.last()) else {
            return Ok(());
        };
        let (first_height, last_id, last_height) = (
            first.header.context.height,
            last.header.block_id,
            last.header.context.height,
        );
        let encoded_len = codec::encode(&blocks).map_or(0, |b| b.len());
        let full = blocks.len() == MAX_SYNC_BLOCKS || encoded_len >= MAX_SYNC_BYTES;

        let mut first_ack = None;
        for blk in blocks {
            let ack = self.import_block(Arc::new(blk), peer_id).await;
            if let ImportAck::Invalid(reason) = ack {
                return Err(Disconnect::Ban(INVALID_BAN, reason));
            }
            first_ack.get_or_insert(ack);
        }

        if first_ack == Some(ImportAck::Orphan) {
            // Parent unknown and not pending: the fork point is lower (§4.7).
            if first_height == 1 {
                warn!(peer = peer_id, "genesis mismatch at height 1");
                return Err(Disconnect::Closed);
            }
            sync.lookback = sync.lookback.saturating_mul(2);
            if sync.lookback > MAX_REORG_DEPTH {
                warn!(peer = peer_id, "no common ancestor within reorg depth");
                return Err(Disconnect::Closed);
            }
            sync.from = sync.from.saturating_sub(sync.lookback).max(1);
            self.send_sync_request(write_tx, sync);
            return Ok(());
        }

        if full || self.peer_best_height(peer_id) > last_height {
            if self.has_block(last_id).await {
                sync.from = last_height + 1;
                self.send_sync_request(write_tx, sync);
            } else {
                // Verification is sequential: wait for the batch to be applied (§4.7).
                sync.awaiting = Some((last_id, last_height));
                sync.deadline = Some(TokioInstant::now() + SYNC_TIMEOUT);
            }
        }
        Ok(())
    }

    fn start_sync(
        &self,
        write_tx: &mpsc::Sender<WireMessage>,
        sync: &mut SyncState,
        hint_height: u64,
    ) {
        let our_best = self.status_rx.borrow().tip.height;
        sync.lookback = SYNC_LOOKBACK;
        sync.awaiting = None;
        sync.from = hint_height
            .min(our_best + 1)
            .saturating_sub(SYNC_LOOKBACK)
            .max(1);
        self.send_sync_request(write_tx, sync);
    }

    fn send_sync_request(&self, write_tx: &mpsc::Sender<WireMessage>, sync: &mut SyncState) {
        sync.outstanding = true;
        sync.deadline = Some(TokioInstant::now() + SYNC_TIMEOUT);
        let _ = write_tx.try_send(WireMessage::SyncRequest {
            from_height: sync.from,
        });
    }

    async fn has_block(&self, id: Digest) -> bool {
        let (tx, rx) = oneshot::channel();
        if self
            .chain_tx
            .send(ChainCmd::HasBlock { id, reply: tx })
            .await
            .is_err()
        {
            return false;
        }
        rx.await.unwrap_or(false)
    }

    async fn import_block(&self, block: Arc<Block>, peer_id: PeerId) -> ImportAck {
        let (tx, rx) = oneshot::channel();
        let cmd = ChainCmd::ImportBlock {
            block,
            origin: Origin::Peer(peer_id),
            ack: Some(tx),
        };
        if self.chain_tx.send(cmd).await.is_err() {
            return ImportAck::Duplicate;
        }
        rx.await.unwrap_or(ImportAck::Duplicate)
    }
}
EOF

cat << 'EOF' > node/src/rpc.rs
//! Axum JSON RPC and embedded web explorer (`node::rpc`, §9).

use std::collections::BTreeMap;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use axum::extract::{DefaultBodyLimit, Query, State};
use axum::http::{HeaderValue, StatusCode, header};
use axum::response::{Html, IntoResponse, Response};
use axum::routing::{get, post};
use axum::{Json, Router};
use chain::{BlockSummary, compute_client_digest};
use ledger::StateCategory;
use primitives::TOTAL_SUPPLY;
use scivm::CONSENSUS_WEIGHT;
use serde::{Deserialize, Serialize};
use tokio::net::TcpListener;
use tokio::sync::{mpsc, oneshot, watch};
use wire::{
    CategoryDelta, DOT_LEN, Digest, FeeTransition, JobPayload, JobTransaction, WIRE_VERSION,
};

use crate::chain_actor::{ChainCmd, Origin, StatusSnapshot};
use crate::engine::ConsensusEngine;
use crate::mempool::{MempoolCmd, MempoolReject, MempoolView};
use crate::net::PeerManager;

const INDEX_HTML: &str = include_str!("../static/index.html");

#[derive(Clone)]
struct RpcState {
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    mempool_view: watch::Receiver<Arc<MempoolView>>,
    chain_tx: mpsc::Sender<ChainCmd>,
    mempool_tx: mpsc::Sender<MempoolCmd>,
    engine: Arc<ConsensusEngine>,
    peer_manager: Arc<PeerManager>,
}

/// Spawns the Axum HTTP server and returns the bound local address (§9.1).
#[allow(clippy::too_many_arguments)]
pub async fn spawn_rpc_server(
    listen_addr: SocketAddr,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    mempool_view: watch::Receiver<Arc<MempoolView>>,
    chain_tx: mpsc::Sender<ChainCmd>,
    mempool_tx: mpsc::Sender<MempoolCmd>,
    engine: Arc<ConsensusEngine>,
    peer_manager: Arc<PeerManager>,
    mut shutdown_rx: watch::Receiver<bool>,
) -> std::io::Result<SocketAddr> {
    let state = RpcState {
        status_rx,
        mempool_view,
        chain_tx,
        mempool_tx,
        engine,
        peer_manager,
    };
    let app = Router::new()
        .route("/", get(handle_index))
        .route("/api/status", get(handle_status))
        .route("/api/blocks", get(handle_blocks))
        .route("/api/submit_job", post(handle_submit_job))
        .layer(DefaultBodyLimit::max(65_536))
        .with_state(state);

    let listener = TcpListener::bind(listen_addr).await?;
    let local_addr = listener.local_addr()?;
    tokio::spawn(async move {
        let _ = axum::serve(listener, app)
            .with_graceful_shutdown(async move {
                while !*shutdown_rx.borrow() {
                    if shutdown_rx.changed().await.is_err() {
                        break;
                    }
                }
            })
            .await;
    });
    Ok(local_addr)
}

async fn handle_index() -> impl IntoResponse {
    (
        [(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"))],
        Html(INDEX_HTML),
    )
}

// ---------------------------------------------------------------------------
// GET /api/status (§9.3)
// ---------------------------------------------------------------------------

#[derive(Serialize)]
struct StatusResponse {
    chain: ChainInfoDto,
    node: NodeInfoDto,
    tip: TipInfoDto,
    mining: MiningInfoDto,
    mempool: MempoolInfoDto,
    ledger: LedgerInfoDto,
    commercial_consensus_weight: u64,
}

#[derive(Serialize)]
struct ChainInfoDto {
    name: String,
    chain_id: String,
    genesis_id: String,
    wire_version: u32,
    blocks_per_epoch: u64,
    target_block_secs: u64,
}

#[derive(Serialize)]
struct NodeInfoDto {
    owner_id: String,
    peers: usize,
    uptime_secs: u64,
}

#[derive(Serialize)]
struct TipInfoDto {
    height: u64,
    block_id: String,
    time_bucket: u64,
    epoch: u64,
    cumulative_weight: String,
    seal_target: String,
    share_target: String,
    expected_attempts_per_seal: String,
}

#[derive(Serialize)]
struct MiningInfoDto {
    enabled: bool,
    threads: usize,
    attempts_per_sec: f64,
    shares_found: u64,
    seals_found: u64,
}

#[derive(Serialize)]
struct MempoolInfoDto {
    size: usize,
}

#[derive(Serialize)]
struct CategoryBalanceDto {
    symbol: &'static str,
    name: String,
    atoms: String,
}

#[derive(Serialize)]
struct LedgerInfoDto {
    categories: Vec<CategoryBalanceDto>,
    total: String,
    supply_m: String,
    conserved: bool,
    founder_locked: String,
    segregated_dust: String,
    fee_lots: usize,
    locked_fees: usize,
    pending_payout: String,
    open_jobs: usize,
}

async fn handle_status(State(state): State<RpcState>) -> Json<StatusResponse> {
    let snap = state.status_rx.borrow().clone();
    let mempool_size = state.mempool_view.borrow().size;
    let expected_attempts = u128::MAX / snap.tip.seal_target.0.max(1);
    let categories = StateCategory::ALL
        .iter()
        .map(|&c| CategoryBalanceDto {
            symbol: c.symbol(),
            name: format!("{c:?}"),
            atoms: snap.balances[c.index()].to_string(),
        })
        .collect();
    let supply_m = u128::from(TOTAL_SUPPLY.get());

    Json(StatusResponse {
        chain: ChainInfoDto {
            name: snap.chain_name.clone(),
            chain_id: format!("0x{:08x}", snap.chain_id),
            genesis_id: snap.genesis_id.to_hex(),
            wire_version: WIRE_VERSION,
            blocks_per_epoch: snap.blocks_per_epoch,
            target_block_secs: snap.target_block_secs,
        },
        node: NodeInfoDto {
            owner_id: snap.owner_id.to_string(),
            peers: state.peer_manager.peer_count(),
            uptime_secs: snap.start_instant.elapsed().as_secs(),
        },
        tip: TipInfoDto {
            height: snap.tip.height,
            block_id: snap.tip.id.to_hex(),
            time_bucket: snap.tip.time_bucket,
            epoch: snap.epoch,
            cumulative_weight: snap.tip.cumulative_weight.to_string(),
            seal_target: snap.tip.seal_target.to_hex(),
            share_target: snap.tip.share_target.to_hex(),
            expected_attempts_per_seal: expected_attempts.to_string(),
        },
        mining: MiningInfoDto {
            enabled: state.engine.is_enabled(),
            threads: state.engine.threads(),
            attempts_per_sec: (state.engine.attempts_per_sec() * 10.0).round() / 10.0,
            shares_found: state.engine.shares_found(),
            seals_found: state.engine.seals_found(),
        },
        mempool: MempoolInfoDto { size: mempool_size },
        ledger: LedgerInfoDto {
            categories,
            total: snap.total.to_string(),
            supply_m: supply_m.to_string(),
            conserved: snap.total == supply_m,
            founder_locked: snap.founder_locked.to_string(),
            segregated_dust: snap.segregated_dust.to_string(),
            fee_lots: snap.fee_lots,
            locked_fees: snap.locked_fees,
            pending_payout: snap.pending_payout.to_string(),
            open_jobs: snap.open_jobs,
        },
        commercial_consensus_weight: CONSENSUS_WEIGHT,
    })
}

// ---------------------------------------------------------------------------
// GET /api/blocks (§9.4)
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct BlocksQuery {
    limit: Option<usize>,
    before: Option<u64>,
}

#[derive(Serialize)]
struct BlocksResponse {
    tip_height: u64,
    blocks: Vec<BlockSummaryDto>,
}

#[derive(Serialize)]
struct BlockSummaryDto {
    height: u64,
    block_id: String,
    parent_id: String,
    anchor_id: String,
    miner_owner: String,
    time_bucket: u64,
    attempt_nonce: String,
    epoch: u64,
    seal_ticket: String,
    seal_weight: String,
    cumulative_weight: String,
    jobs: Vec<JobDto>,
    receipts: Vec<ReceiptDto>,
    shares: Vec<ShareDto>,
    header_share: bool,
    fee_transitions: Vec<FeeTransitionDto>,
    balances_after: BTreeMap<&'static str, String>,
    total_after: String,
}

#[derive(Serialize)]
struct JobDto {
    job_id: String,
    tx_id: String,
    executor_owner: String,
    deposit: String,
    queue_fee: String,
    base_fee: String,
}

#[derive(Serialize)]
struct ReceiptDto {
    job_id: String,
    result: String,
    executor_owner: String,
    admitted_at: u64,
}

#[derive(Serialize)]
struct ShareDto {
    work_id: String,
    owner: String,
    height: u64,
    weight: String,
}

#[derive(Serialize)]
struct FeeTransitionDto {
    op: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    job_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    epoch: Option<u64>,
    delta: BTreeMap<&'static str, String>,
}

async fn handle_blocks(
    State(state): State<RpcState>,
    Query(q): Query<BlocksQuery>,
) -> Json<BlocksResponse> {
    let tip_height = state.status_rx.borrow().tip.height;
    let limit = q.limit.unwrap_or(20).min(100);
    let (tx, rx) = oneshot::channel();
    let cmd = ChainCmd::GetBlocks {
        before: q.before,
        limit,
        reply: tx,
    };
    let summaries = if state.chain_tx.send(cmd).await.is_ok() {
        rx.await.unwrap_or_default()
    } else {
        Vec::new()
    };
    Json(BlocksResponse {
        tip_height,
        blocks: summaries.into_iter().map(summary_to_dto).collect(),
    })
}

fn category_map<T: ToString>(values: &[T]) -> BTreeMap<&'static str, String> {
    StateCategory::ALL
        .iter()
        .zip(values)
        .map(|(c, v)| (c.symbol(), v.to_string()))
        .collect()
}

fn fee_transition_dto(ft: &FeeTransition) -> FeeTransitionDto {
    let delta: &CategoryDelta = ft.delta();
    let (op, job_id, epoch) = match ft {
        FeeTransition::ReserveMature { epoch, .. } => ("ReserveMature", None, Some(*epoch)),
        FeeTransition::FwReward { epoch, .. } => ("FwReward", None, Some(*epoch)),
        FeeTransition::EpochBooked { epoch, .. } => ("EpochBooked", None, Some(*epoch)),
        FeeTransition::ResultSettle { job_id, .. } => ("ResultSettle", Some(*job_id), None),
        FeeTransition::EscrowFundAndQueue { job_id, .. } => {
            ("EscrowFundAndQueue", Some(*job_id), None)
        }
        FeeTransition::JobAdmitAndLease { job_id, .. } => ("JobAdmitAndLease", Some(*job_id), None),
    };
    FeeTransitionDto {
        op,
        job_id: job_id.map(|j| j.to_string()),
        epoch,
        delta: category_map(delta),
    }
}

fn summary_to_dto(s: BlockSummary) -> BlockSummaryDto {
    BlockSummaryDto {
        height: s.height,
        block_id: s.block_id.to_hex(),
        parent_id: s.parent_id.to_hex(),
        anchor_id: s.anchor_id.to_hex(),
        miner_owner: s.miner_owner.to_string(),
        time_bucket: s.time_bucket,
        attempt_nonce: s.attempt_nonce.to_string(),
        epoch: s.epoch,
        seal_ticket: s.seal_ticket.to_hex(),
        seal_weight: s.seal_weight.to_string(),
        cumulative_weight: s.cumulative_weight.to_string(),
        jobs: s
            .jobs
            .into_iter()
            .map(|j| JobDto {
                job_id: j.job_id.to_string(),
                tx_id: j.tx_id.to_hex(),
                executor_owner: j.executor_owner.to_string(),
                deposit: j.deposit.to_string(),
                queue_fee: j.queue_fee.to_string(),
                base_fee: j.base_fee.to_string(),
            })
            .collect(),
        receipts: s
            .receipts
            .into_iter()
            .map(|r| ReceiptDto {
                job_id: r.job_id.to_string(),
                result: r.result.to_string(),
                executor_owner: r.executor_owner.to_string(),
                admitted_at: r.admitted_at,
            })
            .collect(),
        shares: s
            .shares
            .into_iter()
            .map(|sh| ShareDto {
                work_id: sh.work_id.to_hex(),
                owner: sh.owner.to_string(),
                height: sh.height,
                weight: sh.weight.to_string(),
            })
            .collect(),
        header_share: s.header_share,
        fee_transitions: s.fee_transitions.iter().map(fee_transition_dto).collect(),
        balances_after: category_map(&s.balances_after),
        total_after: s.total_after.to_string(),
    }
}

// ---------------------------------------------------------------------------
// POST /api/submit_job (§9.5)
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct SubmitJobRequest {
    client: Option<String>,
    queue_fee: Option<String>,
    base_fee: Option<String>,
    v_exec: Option<String>,
    v_da: Option<String>,
    v_ref: Option<String>,
    expiry_blocks: Option<u64>,
    nonce: Option<String>,
    payload: SubmitJobPayloadDto,
}

#[derive(Deserialize)]
struct SubmitJobPayloadDto {
    #[serde(rename = "type")]
    payload_type: String,
    xs: Vec<i64>,
    ys: Vec<i64>,
}

#[derive(Serialize)]
struct SubmitJobResponse {
    tx_id: String,
    job_id: String,
    deposit: String,
    total_charge: String,
    expected_result: String,
    expiry_height: u64,
    status: &'static str,
}

#[derive(Serialize)]
struct RpcErrorBody {
    error: &'static str,
    message: String,
}

/// An RPC error: HTTP status, stable error code and message (§9.1).
struct ApiError {
    status: StatusCode,
    code: &'static str,
    message: String,
}

impl ApiError {
    fn new(status: StatusCode, code: &'static str, message: impl Into<String>) -> Self {
        Self {
            status,
            code,
            message: message.into(),
        }
    }

    fn bad_request(message: impl Into<String>) -> Self {
        Self::new(StatusCode::BAD_REQUEST, "bad_request", message)
    }

    fn invalid_payload(message: impl Into<String>) -> Self {
        Self::new(StatusCode::BAD_REQUEST, "invalid_payload", message)
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let body = RpcErrorBody {
            error: self.code,
            message: self.message,
        };
        (self.status, Json(body)).into_response()
    }
}

fn parse_u64_field(opt: Option<String>, default: u64, name: &str) -> Result<u64, ApiError> {
    match opt {
        Some(s) => s
            .parse::<u64>()
            .map_err(|_| ApiError::bad_request(format!("{name} must be a decimal u64 string"))),
        None => Ok(default),
    }
}

/// Largest integer magnitude that converts to `f64` exactly.
const MAX_EXACT_INT: u64 = (1u64 << 53) - 1;

fn to_operands(values: &[i64]) -> Result<Vec<f64>, ApiError> {
    values
        .iter()
        .map(|&v| {
            if v.unsigned_abs() > MAX_EXACT_INT {
                Err(ApiError::invalid_payload("operand magnitude exceeds 2^53"))
            } else {
                Ok(v as f64)
            }
        })
        .collect()
}

fn build_job(req: SubmitJobRequest, tip_height: u64) -> Result<JobTransaction, ApiError> {
    let client = match req.client.as_deref() {
        Some(txt) if !txt.is_empty() => {
            compute_client_digest(txt).map_err(ApiError::bad_request)?
        }
        _ => Digest::ZERO,
    };
    // Defaults: the worked budget of WP (7.17), with 1 PLAU = 10^8 atoms.
    let queue_fee = parse_u64_field(req.queue_fee, 100_000_000, "queue_fee")?;
    let base_fee = parse_u64_field(req.base_fee, 1_000_000_000, "base_fee")?;
    let v_exec = parse_u64_field(req.v_exec, 8_000_000_000, "v_exec")?;
    let v_da = parse_u64_field(req.v_da, 500_000_000, "v_da")?;
    let v_ref = parse_u64_field(req.v_ref, 500_000_000, "v_ref")?;

    let expiry_blocks = req.expiry_blocks.unwrap_or(120);
    if !(1..=10_000).contains(&expiry_blocks) {
        return Err(ApiError::bad_request("expiry_blocks must be in 1..=10000"));
    }
    let nonce = match req.nonce {
        Some(s) => s
            .parse::<u64>()
            .map_err(|_| ApiError::bad_request("nonce must be a decimal u64 string"))?,
        None => {
            let nanos = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos() as u64;
            nanos ^ 0x9e37_79b9_7f4a_7c15
        }
    };

    if req.payload.payload_type != "exact_dot" {
        return Err(ApiError::invalid_payload(
            "payload.type must be 'exact_dot'",
        ));
    }
    if req.payload.xs.len() != DOT_LEN || req.payload.ys.len() != DOT_LEN {
        return Err(ApiError::invalid_payload(format!(
            "xs and ys must each have {DOT_LEN} elements"
        )));
    }
    Ok(JobTransaction {
        client,
        queue_fee,
        base_fee,
        v_exec,
        v_da,
        v_ref,
        expiry_height: tip_height.saturating_add(expiry_blocks),
        nonce,
        payload: JobPayload::ExactDot {
            xs: to_operands(&req.payload.xs)?,
            ys: to_operands(&req.payload.ys)?,
        },
    })
}

async fn handle_submit_job(
    State(state): State<RpcState>,
    Json(req): Json<SubmitJobRequest>,
) -> Result<(StatusCode, Json<SubmitJobResponse>), ApiError> {
    let tip_height = state.status_rx.borrow().tip.height;
    let tx = build_job(req, tip_height)?;
    let expiry_height = tx.expiry_height;

    let unavailable = |what: &str| {
        ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "mempool_full",
            format!("mempool {what}"),
        )
    };
    let (reply_tx, reply_rx) = oneshot::channel();
    let cmd = MempoolCmd::Insert {
        tx,
        origin: Origin::Rpc,
        reply: reply_tx,
    };
    state
        .mempool_tx
        .send(cmd)
        .await
        .map_err(|_| unavailable("actor unavailable"))?;
    let ok = match reply_rx
        .await
        .map_err(|_| unavailable("reply channel closed"))?
    {
        Ok(ok) => ok,
        Err(MempoolReject::Duplicate) => {
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "duplicate",
                "job transaction already in mempool",
            ));
        }
        Err(MempoolReject::Full) => return Err(unavailable("is full")),
        Err(MempoolReject::Invalid { code, message }) => {
            return Err(ApiError::new(StatusCode::BAD_REQUEST, code, message));
        }
    };
    Ok((
        StatusCode::ACCEPTED,
        Json(SubmitJobResponse {
            tx_id: ok.tx_id.to_hex(),
            job_id: ok.job_id.to_string(),
            deposit: ok.deposit.to_string(),
            total_charge: ok.total_charge.to_string(),
            expected_result: ok.expected_result.to_string(),
            expiry_height,
            status: "pending",
        }),
    ))
}
EOF

