            <th>Status</th>
            <th class="num">Reference Dot</th>
            <th class="num">Settled Result</th>
          </tr>
        </thead>
        <tbody id="myjobs-tbody"></tbody>
      </table>
    </section>
  </div>
</main>

<script>
(function() {
  const SUPPLY_M = 1500000000000000n;
  const LOG_M = Math.log10(1 + Number(SUPPLY_M));
  const COLORS = ["#2563eb", "#64748b", "#d97706", "#94a3b8", "#a855f7", "#10b981", "#f59e0b", "#ec4899"];
  const INACTIVE = new Set(["S_z", "B_bond", "V_L2"]);

  let lastTipHeight = -1;
  const knownHeights = new Set();
  const expandedHeights = new Set();
  let latestBlocks = [];
  let xs = [];
  let ys = [];
  let localDot = 0n;
  let myJobs = loadMyJobs();

  function loadMyJobs() {
    try {
      const raw = localStorage.getItem("plauthium_my_jobs");
      const parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
      return [];
    }
  }
  function saveMyJobs() {
    try {
      localStorage.setItem("plauthium_my_jobs", JSON.stringify(myJobs));
    } catch (_) {}
  }

  function esc(value) {
    return String(value).replace(/[&<>"']/g, ch => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
    })[ch]);
  }

  function groupBigInt(valStr) {
    const s = String(valStr);
    const neg = s.startsWith("-");
    const digits = neg ? s.slice(1) : s;
    const out = digits.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return neg ? "-" + out : out;
  }

  function atomsToPlau(atomsStr) {
    const a = BigInt(atomsStr);
    const whole = a / 100000000n;
    const frac = (a % 100000000n).toString().padStart(8, "0");
    return groupBigInt(whole.toString()) + "." + frac;
  }

  function plauToAtoms(plauStr) {
    const s = plauStr.trim();
    if (!/^\d+(\.\d{1,8})?$/.test(s)) throw new Error("Invalid PLAU amount: " + s);
    const parts = s.split(".");
    const whole = BigInt(parts[0]) * 100000000n;
    const frac = parts[1] ? BigInt(parts[1].padEnd(8, "0")) : 0n;
    return (whole + frac).toString();
  }

  // xorshift64* stream; operands stay in [-(2^23 - 1), 2^23 - 1].
  function generateOperands() {
    let seed = BigInt(document.getElementById("f-seed").value || "1") & 0xffffffffffffffffn;
    if (seed === 0n) seed = 1n;
    function nextRand() {
      seed ^= seed >> 12n;
      seed = (seed ^ (seed << 25n)) & 0xffffffffffffffffn;
      seed ^= seed >> 27n;
      const r = (seed * 2685821657736338717n) & 0xffffffffffffffffn;
      return Number(r & 0xffffffn) - 8388607;
    }
    xs = [];
    ys = [];
    localDot = 0n;
    for (let i = 0; i < 512; i++) {
      const a = Math.max(-8388607, Math.min(8388607, nextRand()));
      const b = Math.max(-8388607, Math.min(8388607, nextRand()));
      xs.push(a);
      ys.push(b);
      localDot += BigInt(a) * BigInt(b);
    }
    document.getElementById("local-dot").textContent = groupBigInt(localDot.toString());
  }

  document.getElementById("btn-gen").addEventListener("click", generateOperands);

  document.getElementById("btn-submit").addEventListener("click", async function() {
    const msgEl = document.getElementById("submit-msg");
    msgEl.textContent = "Submitting...";
    try {
      const body = {
        client: document.getElementById("f-client").value.trim(),
        queue_fee: plauToAtoms(document.getElementById("f-qfee").value),
        base_fee: plauToAtoms(document.getElementById("f-bfee").value),
        v_exec: plauToAtoms(document.getElementById("f-vexec").value),
        v_da: plauToAtoms(document.getElementById("f-vda").value),
        v_ref: plauToAtoms(document.getElementById("f-vref").value),
        expiry_blocks: 120,
        payload: { type: "exact_dot", xs: xs, ys: ys }
      };
      const resp = await fetch("/api/submit_job", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body)
      });
      const text = await resp.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (_) {
        msgEl.textContent = "Error (HTTP " + resp.status + "): " + text;
        return;
      }
      if (!resp.ok) {
        msgEl.textContent = "Error (" + data.error + "): " + data.message;
        return;
      }
      document.getElementById("server-dot").textContent = groupBigInt(data.expected_result);
      const match = BigInt(data.expected_result) === localDot;
      msgEl.textContent = "Accepted job_id=" + data.job_id + " (Ozaki-II match=" + (match ? "YES ✓" : "NO ✗") + ")";
      myJobs.unshift({
        job_id: data.job_id,
        tx_id: data.tx_id,
        ref_dot: localDot.toString(),
        expected_result: data.expected_result
      });
      myJobs = myJobs.slice(0, 25);
      saveMyJobs();
      renderMyJobs();
    } catch (e) {
      msgEl.textContent = "Submit failed: " + e.message;
    }
  });

  function renderLedger(ledger) {
    const stackEl = document.getElementById("stack-bar");
    const tbody = document.getElementById("cat-tbody");
    stackEl.innerHTML = "";
    tbody.innerHTML = "";

    let sum = 0n;
    ledger.categories.forEach((c, idx) => {
      const atoms = BigInt(c.atoms);
      sum += atoms;
      const pct = Number((atoms * 1000000n) / SUPPLY_M) / 10000;
      const seg = document.createElement("div");
      seg.className = "stack-seg";
      seg.style.background = COLORS[idx % COLORS.length];
      seg.style.width = pct + "%";
      if (atoms > 0n) seg.style.minWidth = "2px";
      seg.title = c.symbol + ": " + groupBigInt(c.atoms) + " atoms";
      stackEl.appendChild(seg);

      const ppm = ((atoms * 1000000n) / SUPPLY_M).toString();
      const logPct = atoms > 0n ? Math.min(100, (Math.log10(1 + Number(atoms)) / LOG_M) * 100) : 0;
      const inactiveNote = INACTIVE.has(c.symbol) ? ' <span class="muted">(inactive in v0)</span>' : "";

      const tr = document.createElement("tr");
      tr.innerHTML =
        '<td class="mono"><b>' + esc(c.symbol) + '</b></td>' +
        '<td>' + esc(c.name) + inactiveNote + '</td>' +
        '<td class="num">' + groupBigInt(c.atoms) + '</td>' +
        '<td class="num">' + atomsToPlau(c.atoms) + '</td>' +
        '<td class="num">' + groupBigInt(ppm) + '</td>' +
        '<td><div class="log-bar-wrap"><div class="log-bar" style="width:' + logPct.toFixed(1) + '%;background:' + COLORS[idx % COLORS.length] + '"></div></div></td>';
      tbody.appendChild(tr);
    });

    const badge = document.getElementById("inv-badge");
    if (sum === SUPPLY_M && ledger.conserved) {
      badge.className = "badge ok";
      badge.textContent = "Σ = M = 1,500,000,000,000,000 ✓";
    } else {
      badge.className = "badge err";
      badge.textContent = "INVARIANT ALERT: Σ - M = " + (sum - SUPPLY_M).toString();
    }

    document.getElementById("s-flocked").textContent = groupBigInt(ledger.founder_locked);
    document.getElementById("s-dust").textContent = groupBigInt(ledger.segregated_dust);
    document.getElementById("s-lots").textContent = ledger.fee_lots;
    document.getElementById("s-locked").textContent = ledger.locked_fees;
    document.getElementById("s-pending").textContent = groupBigInt(ledger.pending_payout);
    document.getElementById("s-openjobs").textContent = ledger.open_jobs;
  }

  function renderBlocks(blocks) {
    const tbody = document.getElementById("blocks-tbody");
    tbody.innerHTML = "";
    for (let i = 0; i < blocks.length; i++) {
      const b = blocks[i];
      const prev = blocks[i + 1];
      const dt = prev ? (b.time_bucket - prev.time_bucket) + "s" : "-";

      let dU = 0n;
      let dRl = 0n;
      (b.fee_transitions || []).forEach(ft => {
        if (ft.delta && ft.delta.U) dU += BigInt(ft.delta.U);
        if (ft.delta && ft.delta.R_l) dRl += BigInt(ft.delta.R_l);
      });

      const isNew = knownHeights.size > 0 && !knownHeights.has(b.height);
      knownHeights.add(b.height);

      const tr = document.createElement("tr");
      tr.className = "clickable" + (isNew ? " flash-row" : "");
      const star = b.header_share ? " ★" : "";
      tr.innerHTML =
        '<td class="mono"><b>' + b.height + '</b></td>' +
        '<td class="mono">' + esc(b.block_id.slice(0, 12)) + '..</td>' +
        '<td class="mono">' + esc(b.miner_owner) + '</td>' +
        '<td class="num">' + b.jobs.length + '</td>' +
        '<td class="num">' + b.receipts.length + '</td>' +
        '<td class="num">' + b.shares.length + star + '</td>' +
        '<td class="num">' + (dU >= 0n ? "+" : "") + groupBigInt(dU.toString()) + '</td>' +
        '<td class="num">' + (dRl >= 0n ? "+" : "") + groupBigInt(dRl.toString()) + '</td>' +
        '<td class="num">' + dt + '</td>';

      tr.addEventListener("click", function() {
        if (expandedHeights.has(b.height)) expandedHeights.delete(b.height);
        else expandedHeights.add(b.height);
        renderBlocks(latestBlocks);
      });
      tbody.appendChild(tr);

      if (expandedHeights.has(b.height)) {
        const dtr = document.createElement("tr");
        const td = document.createElement("td");
        td.colSpan = 9;
        td.className = "details-cell";
        const ftLines = (b.fee_transitions || []).map(ft =>
          esc(ft.op) + (ft.job_id ? " (job=" + esc(ft.job_id) + ")" : "") +
          " ΔU=" + esc(ft.delta.U) + " ΔE_esc=" + esc(ft.delta.E_esc) + " ΔR_a=" + esc(ft.delta.R_a) +
          " ΔR_l=" + esc(ft.delta.R_l) + " ΔP=" + esc(ft.delta.P_pending)
        ).join("<br>");
        const rcLines = (b.receipts || []).map(r =>
          "Receipt job=" + esc(r.job_id) + " executor=" + esc(r.executor_owner) + " result=" + esc(r.result)
        ).join("<br>");
        td.innerHTML = (ftLines || "No fee transitions") + (rcLines ? "<br>" + rcLines : "");
        dtr.appendChild(td);
        tbody.appendChild(dtr);
      }
    }
  }

  function renderMyJobs() {
    const tbody = document.getElementById("myjobs-tbody");
    tbody.innerHTML = "";
    myJobs.forEach(mj => {
      let status = "pending";
      let settledResult = "-";
      for (const b of latestBlocks) {
        for (const r of (b.receipts || [])) {
          if (r.job_id === mj.job_id) {
            status = "settled @" + b.height + " (owner " + r.executor_owner + ")";
            settledResult = groupBigInt(r.result) + (r.result === mj.ref_dot ? " ✓" : " ✗");
          }
        }
        if (status === "pending") {
          for (const j of (b.jobs || [])) {
            if (j.job_id === mj.job_id) {
              status = "admitted @" + b.height + " (lease owner " + j.executor_owner + ")";
            }
          }
        }
      }
      const tr = document.createElement("tr");
      tr.innerHTML =
        '<td class="mono">' + esc(mj.job_id) + '</td>' +
        '<td class="mono">' + esc(status) + '</td>' +
        '<td class="num">' + groupBigInt(esc(mj.ref_dot)) + '</td>' +
        '<td class="num">' + esc(settledResult) + '</td>';
      tbody.appendChild(tr);
    });
  }

  async function poll() {
    if (document.hidden) return;
    const banner = document.getElementById("offline-banner");
    try {
      const resp = await fetch("/api/status");
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const st = await resp.json();
      banner.style.display = "none";

      document.getElementById("h-chain").textContent = st.chain.name;
      document.getElementById("h-chain-id").textContent = st.chain.chain_id;
      document.getElementById("h-owner").textContent = st.node.owner_id;
      document.getElementById("h-peers").textContent = st.node.peers;
      document.getElementById("h-height").textContent = st.tip.height;
      document.getElementById("h-tip-id").textContent = st.tip.block_id.slice(0, 10) + "..";
      document.getElementById("h-epoch").textContent = st.tip.epoch;
      document.getElementById("h-rate").textContent = st.mining.attempts_per_sec.toFixed(1);
      document.getElementById("h-exp").textContent = st.tip.expected_attempts_per_seal;
      document.getElementById("h-mempool").textContent = st.mempool.size;
      document.getElementById("s-cw").textContent = st.commercial_consensus_weight;

      renderLedger(st.ledger);

      if (st.tip.height !== lastTipHeight) {
        lastTipHeight = st.tip.height;
        const bResp = await fetch("/api/blocks?limit=20");
        if (bResp.ok) {
          const bData = await bResp.json();
          latestBlocks = bData.blocks || [];
          renderBlocks(latestBlocks);
          renderMyJobs();
        }
      }
    } catch (_) {
      banner.style.display = "block";
    }
  }

  generateOperands();
  renderMyJobs();
  poll();
  setInterval(poll, 2000);
})();
</script>
</body>
</html>
EOF

cat << 'EOF' > node/tests/testnet_integration.rs
//! Three-node integration test covering acceptance criteria A2–A6 (§11).
//!
//! Real 512x512 tiles are mined and verified, so run it with `--release`.

#![forbid(unsafe_code)]

use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use node::chain_actor::{ChainCmd, Origin};
use node::cli::RunArgs;
use node::mempool::MempoolCmd;
use node::{NodeHandle, start_node};
use primitives::TOTAL_SUPPLY;
use serde_json::Value;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio::sync::oneshot;
use tokio::time::Instant;
use wire::{DifficultyMode, Digest, GenesisConfig, JobPayload, JobTransaction, Target};

const PHASE_TIMEOUT: Duration = Duration::from_secs(240);

fn temp_test_dir(label: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    std::env::temp_dir().join(format!("plauthium-it-{label}-{nanos}"))
}

/// About 64 attempts per seal (~1.5 s blocks with three miners) and roughly two
/// verified shares per block, so validation keeps up with production.
fn test_genesis() -> GenesisConfig {
    let mut g = GenesisConfig::default_testnet(1_700_000_000);
    g.initial_seal_target = Target(u128::MAX / 64);
    g.share_ratio = 2;
    g.difficulty = DifficultyMode::Fixed;
    g.blocks_per_epoch = 5;
    g.settle_delay = 1;
    g.share_maturity_depth = 1;
    g.snapshot_window = 30;
    g.share_inclusion_window = 15;
    g
}

async fn start(
    dir: &Path,
    owner: u64,
    genesis: &Path,
    peers: Vec<SocketAddr>,
    mine: bool,
    reset: bool,
) -> NodeHandle {
    start_node(RunArgs {
        data_dir: dir.join(format!("n{owner}")),
        owner_id: owner,
        genesis: Some(genesis.to_path_buf()),
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers,
        mining_threads: 1,
        no_mine: !mine,
        verify_threads: Some(2),
        reset,
    })
    .await
    .unwrap()
}

fn height(n: &NodeHandle) -> u64 {
    n.status_rx.borrow().tip.height
}

fn tip_id(n: &NodeHandle) -> Digest {
    n.status_rx.borrow().tip.id
}

async fn wait_until(what: &str, mut cond: impl FnMut() -> bool) {
    let deadline = Instant::now() + PHASE_TIMEOUT;
    while !cond() {
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

/// Stops mining and waits until every node has the same tip and balances.
///
/// With mining stopped, two equal-weight tips both survive (a tie keeps the current
/// tip, §6.5), so a tie is broken by letting `tiebreaker` mine one more block.
async fn converge(nodes: &[&NodeHandle], tiebreaker: &NodeHandle) {
    for n in nodes {
        n.engine.set_enabled(false);
    }
    for _round in 0..5 {
        let deadline = Instant::now() + Duration::from_secs(20);
        while Instant::now() < deadline {
            let first = tip_id(nodes[0]);
            if nodes.iter().all(|n| tip_id(n) == first) {
                let balances = nodes[0].status_rx.borrow().balances;
                assert!(
                    nodes
                        .iter()
                        .all(|n| n.status_rx.borrow().balances == balances)
                );
                return;
            }
            tokio::time::sleep(Duration::from_millis(100)).await;
        }
        let h = height(tiebreaker);
        tiebreaker.engine.set_enabled(true);
        wait_until("tie-breaking block", || height(tiebreaker) > h).await;
        tiebreaker.engine.set_enabled(false);
    }
    panic!("nodes did not converge on one tip");
}

async fn http(addr: SocketAddr, method: &str, path: &str, body: Option<&str>) -> (u16, String) {
    let mut stream = TcpStream::connect(addr).await.unwrap();
    let body = body.unwrap_or("");
    let req = format!(
        "{method} {path} HTTP/1.1\r\nHost: {addr}\r\nContent-Type: application/json\r\n\
         Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    stream.write_all(req.as_bytes()).await.unwrap();
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).await.unwrap();
    let text = String::from_utf8_lossy(&resp).to_string();
    let (head, body) = text.split_once("\r\n\r\n").unwrap();
    let status = head.split(' ').nth(1).unwrap().parse().unwrap();
    (status, body.to_string())
}

async fn status_json(n: &NodeHandle) -> Value {
    let (code, body) = http(n.rpc_addr, "GET", "/api/status", None).await;
    assert_eq!(code, 200);
    let v: Value = serde_json::from_str(&body).unwrap();
    // A6: the explorer's data source always reports a conserved supply.
    assert_eq!(v["ledger"]["conserved"], Value::Bool(true));
    let sum: u128 = v["ledger"]["categories"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["atoms"].as_str().unwrap().parse::<u128>().unwrap())
        .sum();
    assert_eq!(sum, u128::from(TOTAL_SUPPLY.get()));
    v
}

async fn mempool_size(n: &NodeHandle) -> usize {
    let (tx, rx) = oneshot::channel();
    n.mempool_tx
        .send(MempoolCmd::Stats { reply: tx })
        .await
        .unwrap();
    rx.await.unwrap()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn acceptance_criteria_a2_to_a6() {
    let base_dir = temp_test_dir("full");
    std::fs::create_dir_all(&base_dir).unwrap();
    let genesis_path = base_dir.join("genesis.json");
    let genesis_json = serde_json::to_string_pretty(&test_genesis()).unwrap();
    std::fs::write(&genesis_path, genesis_json).unwrap();

    let n1 = start(&base_dir, 1, &genesis_path, vec![], true, true).await;
    let n2 = start(&base_dir, 2, &genesis_path, vec![n1.p2p_addr], true, true).await;
    let n3 = start(
        &base_dir,
        3,
        &genesis_path,
        vec![n1.p2p_addr, n2.p2p_addr],
        true,
        true,
    )
    .await;

    // A6: the explorer is served at `/` with the conservation badge.
    let (code, html) = http(n1.rpc_addr, "GET", "/", None).await;
    assert_eq!(code, 200);
    assert!(html.contains("Σ = M = 1,500,000,000,000,000 ✓"));
    status_json(&n1).await;

    // A2 (part 1): all nodes advance; the epoch-1 booking is paid into U at h = 10.
    wait_until("height >= 11 on all nodes", || {
        [&n1, &n2, &n3].iter().all(|n| height(n) >= 11)
    })
    .await;

    // A3: submit a job to node 1 over HTTP; it must settle on node 3 with the exact result.
    let xs: Vec<i64> = (1..=512).collect();
    let ys: Vec<i64> = (1..=512).rev().collect();
    let direct_dot: i128 = xs.iter().zip(&ys).map(|(&a, &b)| i128::from(a * b)).sum();
    let body = serde_json::json!({
        "client": "a3-client",
        "nonce": "777",
        "payload": { "type": "exact_dot", "xs": xs, "ys": ys }
    })
    .to_string();
    let (code, resp) = http(n1.rpc_addr, "POST", "/api/submit_job", Some(&body)).await;
    assert_eq!(code, 202, "{resp}");
    let resp: Value = serde_json::from_str(&resp).unwrap();
    assert_eq!(resp["expected_result"], direct_dot.to_string());
    assert_eq!(resp["deposit"], "10000000000");
    let job_id = resp["job_id"].as_str().unwrap().to_string();
    let (code, _) = http(n1.rpc_addr, "POST", "/api/submit_job", Some(&body)).await;
    assert_eq!(code, 409, "resubmitting the same job is a duplicate");

    let supply = TOTAL_SUPPLY.get().to_string();
    let deadline = Instant::now() + PHASE_TIMEOUT;
    let settled_at = loop {
        assert!(
            Instant::now() < deadline,
            "timed out waiting for A3 settlement"
        );
        status_json(&n3).await;
        let (code, blocks) = http(n3.rpc_addr, "GET", "/api/blocks?limit=100", None).await;
        assert_eq!(code, 200);
        let blocks: Value = serde_json::from_str(&blocks).unwrap();
        let blocks = blocks["blocks"].as_array().unwrap();
        assert!(
            blocks
                .iter()
                .all(|b| b["total_after"].as_str() == Some(supply.as_str()))
        );
        let receipt = blocks.iter().find_map(|b| {
            b["receipts"]
                .as_array()
                .unwrap()
                .iter()
                .find(|r| r["job_id"] == job_id.as_str())
                .map(|r| (b["height"].as_u64().unwrap(), r["result"].clone()))
        });
        if let Some((h, result)) = receipt {
            assert_eq!(result, direct_dot.to_string());
            break h;
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
    };
    assert!(settled_at >= 11);

    // A2: stop mining; tips and the 8 balances converge.
    converge(&[&n1, &n2, &n3], &n1).await;
    for n in [&n1, &n2, &n3] {
        let st = n.status_rx.borrow().clone();
        assert_eq!(st.total, u128::from(TOTAL_SUPPLY.get()));
        assert_eq!(st.balances[2], 0, "E_esc drains once the job has settled");
    }

    // A4: stop node 3, mine 10 blocks on nodes 1 and 2, restart node 3 on its data dir.
    let pre_stop_h = height(&n3);
    let (flush_tx, flush_rx) = oneshot::channel();
    n3.chain_tx
        .send(ChainCmd::FlushAndClose { reply: flush_tx })
        .await
        .unwrap();
    flush_rx.await.unwrap();
    n3.stop().await;

    n1.engine.set_enabled(true);
    n2.engine.set_enabled(true);
    wait_until("10 more blocks on node 1", || {
        height(&n1) >= pre_stop_h + 10
    })
    .await;
    converge(&[&n1, &n2], &n1).await;

    let n3 = start(
        &base_dir,
        3,
        &genesis_path,
        vec![n1.p2p_addr, n2.p2p_addr],
        false,
        false,
    )
    .await;
    assert!(
        height(&n3) >= pre_stop_h,
        "blocks.log is replayed before start_node returns"
    );
    wait_until("node 3 resync", || tip_id(&n3) == tip_id(&n1)).await;
    assert_eq!(
        n3.status_rx.borrow().balances,
        n1.status_rx.borrow().balances
    );

    // A5: partition {1} | {2, 3}; mine 1 block on node 1 and 3 on node 2, then reconnect.
    n1.peer_manager.set_network_paused(true);
    let base_h = height(&n1);
    let part_tx = JobTransaction {
        client: chain::compute_client_digest("partition-job").unwrap(),
        queue_fee: 100_000_000,
        base_fee: 1_000_000_000,
        v_exec: 8_000_000_000,
        v_da: 500_000_000,
        v_ref: 500_000_000,
        expiry_height: base_h + 500,
        nonce: 9_999,
        payload: JobPayload::ExactDot {
            xs: vec![2.0; 512],
            ys: vec![3.0; 512],
        },
    };
    let (p_tx, p_rx) = oneshot::channel();
    n1.mempool_tx
        .send(MempoolCmd::Insert {
            tx: part_tx,
            origin: Origin::Rpc,
            reply: p_tx,
        })
        .await
        .unwrap();
    p_rx.await.unwrap().unwrap();
    // Let the template pick the job up before mining.
    tokio::time::sleep(Duration::from_millis(800)).await;

    n1.engine.set_enabled(true);
    wait_until("node 1 mines inside the partition", || height(&n1) > base_h).await;
    n1.engine.set_enabled(false);
    tokio::time::sleep(Duration::from_millis(300)).await;
    let n1_branch_tip = tip_id(&n1);

    n2.engine.set_enabled(true);
    wait_until("node 2 mines 3 blocks", || height(&n2) >= base_h + 3).await;
    n2.engine.set_enabled(false);
    wait_until("node 3 follows node 2", || tip_id(&n3) == tip_id(&n2)).await;
    assert_ne!(tip_id(&n2), n1_branch_tip, "the partition holds");

    n1.peer_manager.set_network_paused(false);
    wait_until("node 1 reorgs to the heavier branch", || {
        tip_id(&n1) == tip_id(&n2)
    })
    .await;
    assert_eq!(
        n1.status_rx.borrow().balances,
        n2.status_rx.borrow().balances
    );
    assert!(
        mempool_size(&n1).await >= 1,
        "the losing branch's job is back in node 1's mempool"
    );
    status_json(&n1).await;
    status_json(&n2).await;
    status_json(&n3).await;

    n1.stop().await;
    n2.stop().await;
    n3.stop().await;
    let _ = std::fs::remove_dir_all(&base_dir);
}
EOF

cat << 'EOF' > poc/Cargo.toml
[package]
name = "poc"
version = "0.1.0"
edition = "2024"
description = "Plauthium proof-of-concept: one mock block transition across all five protocol modules"

[dependencies]
primitives = { path = "../primitives" }
work = { path = "../work" }
scivm = { path = "../scivm" }
scheduler = { path = "../scheduler" }
ledger = { path = "../ledger" }

[lints]
workspace = true
EOF

cat << 'EOF' > poc/src/main.rs
//! Plauthium proof of concept: one mock block transition across all five modules.
//!
//! a) Genesis ledger: Emission Reserve and Founder Allocation.
//! b) Fresh Work: expand a seed into two 512 x 512 INT8 tiles, compute the
//!    exact INT32 product and certify it with six Freivalds rounds.
//! c) Scheduler: sequential D'Hondt lease allocation over discrete ShareIDs.
//! d) Ledger: lock a Base Fee, mature it into an independent fee lot and pay
//!    Fresh Work rewards from it with segregated rounding dust.
//! e) ASCII summary.
//!
//! Hashes, XOFs and signatures are placeholders (see the `primitives` crate).

use std::error::Error;

use ledger::{
    BLOCKS_PER_DAY, FOUNDER_ALLOCATION, JobId, Ledger, LedgerParams, StateCategory,
    VESTING_TRANCHES,
};
use primitives::{Atoms, DomainSeparatedHash, Mersenne61, TOTAL_SUPPLY};
use scheduler::{Allocation, OwnerId, ShareID, dhondt_allocation};
use scivm::{CONSENSUS_WEIGHT, OzakiIIProfile, RoundingMode};
use work::{
    ACCUMULATION_BOUND, CLASSICAL_MACS, DEFAULT_FREIVALDS_ROUNDS, FREIVALDS_FIELD_MULS,
    FreshWorkContext, FreshWorkIds, TILE_DIM, verify_freivalds_rounds,
};

/// Height of the block this PoC seals.
const BLOCK_HEIGHT: u64 = 1;
/// Execution slots (ready tiles) offered to the scheduler in this batch.
const LEASE_SLOTS: usize = 8;

type PocResult<T> = Result<T, Box<dyn Error>>;

fn main() -> PocResult<()> {
    println!("Plauthium PoC - mock block transition");
    println!("(hash/XOF/signatures are non-cryptographic placeholders)\n");

    // ---------------------------------------------------------------- (a)
    section("a", "Genesis ledger");
    let mut ledger = Ledger::genesis(LedgerParams::poc())?;
    print_categories(&ledger);
    let vesting = *ledger.founder_vesting();
    let first = vesting.tranche(1).ok_or("missing tranche 1")?;
    let last = vesting
        .tranche(VESTING_TRANCHES)
        .ok_or("missing last tranche")?;
    println!(
        "  FounderAllocation: {} tranches inside U; tranche 1 = {} atoms @ h={}, tranche {} @ h={}",
        VESTING_TRANCHES,
        group(first.value.get()),
        first.unlock_height,
        last.day,
        group(last.unlock_height),
    );
    println!(
        "  EmissionReserve:   Genesis lot c_G with A = {} atoms\n",
        group(ledger.fee_lots()[0].principal().get())
    );

    // ---------------------------------------------------------------- (b)
    section(
        "b",
        "Fresh Work: seed -> 512x512 INT8 tiles -> INT32 product",
    );
    let context = mock_context(BLOCK_HEIGHT, 0);
    let instance = context.instance();
    println!(
        "  seed = H512(FW/INPUT/v2, x)       {}..",
        instance.seed.short_hex(16)
    );
    println!(
        "  X, Y = Map(XOF(FW/A|FW/B, seed))  {TILE_DIM}x{TILE_DIM}, entries in [-127, 127], max|X| = {}",
        instance.x.max_abs()
    );
    let product = instance.x.product(&instance.y);
    println!(
        "  Z = XY ({} MACs)         max|Z| = {} <= {}",
        group(CLASSICAL_MACS),
        group(product.max_abs() as u64),
        group(ACCUMULATION_BOUND as u64)
    );
    let accepted =
        verify_freivalds_rounds(&instance.x, &instance.y, &product, DEFAULT_FREIVALDS_ROUNDS);
    let mut forged = product.clone();
    let entry = forged.get(17, 42);
    forged.set(17, 42, if entry > 0 { entry - 1 } else { entry + 1 })?;
    let forged_rejected =
        !verify_freivalds_rounds(&instance.x, &instance.y, &forged, DEFAULT_FREIVALDS_ROUNDS);
    ensure(accepted, "Freivalds rejected the honest product")?;
    ensure(forged_rejected, "Freivalds accepted a forged product")?;
    println!(
        "  Freivalds r_F = {DEFAULT_FREIVALDS_ROUNDS} over F_p (p = {}): honest ACCEPT, forged REJECT",
        Mersenne61::P
    );
    let ids = FreshWorkIds::derive(&context, &product);
    println!("  outputRoot {}..", ids.output_root.short_hex(16));
    println!("  WorkID     {}..  (= ShareID)", ids.work_id.short_hex(16));
    println!("  BlockID    {}..", ids.block_id.short_hex(16));
    println!(
        "  theta_S    {}..  theta_B {}..\n",
        ids.share_ticket.short_hex(8),
        ids.seal_ticket.short_hex(8)
    );

    // ---------------------------------------------------------------- (c)
    section("c", "Scheduler: sequential D'Hondt over discrete ShareIDs");
    let shares = mock_cohort(ids.work_id);
    let allocation = dhondt_allocation(&shares, LEASE_SLOTS)?;
    ensure(
        allocation.assigned() == LEASE_SLOTS,
        "D'Hondt left slots unassigned",
    )?;
    print_allocation(&shares, &allocation);

    // ---------------------------------------------------------------- (d)
    section("d", "Ledger: Base Fee lock -> maturation -> fee-lot payout");
    let weights: Vec<u64> = shares.iter().map(|s| s.weight).collect();

    // Epoch 0 rewards from the Genesis lot give miners spendable outputs in U.
    let (_, genesis_epoch) = ledger.book_epoch(&weights)?;
    ledger.fw_reward(genesis_epoch.booked)?;
    step(
        &ledger,
        "FW_REWARD (epoch 0, Genesis lot)",
        format!(
            "{} paid, {} atoms dust",
            genesis_epoch.booked,
            genesis_epoch.dust.get()
        ),
    )?;

    // The commercial job runs on the SciVM under a bound Ozaki-II profile.
    let profile = OzakiIIProfile {
        version: 1,
        moduli: vec![255, 254, 253, 251, 247, 241, 239, 233],
        inner_dim: TILE_DIM as u64,
        bound_x: 1 << 23,
        bound_y: 1 << 23,
        rounding: RoundingMode::NearestTiesToEven,
    };
    profile.validate()?;
    let (xs, ys) = mock_scientific_operands();
    let dot = profile.exact_dot(&xs, &ys)?;
    let direct: i128 = xs
        .iter()
        .zip(&ys)
        .map(|(&a, &b)| a as i128 * b as i128)
        .sum();
    ensure(dot == direct, "Ozaki-II reconstruction mismatch")?;
    println!(
        "  SciVM Ozaki-II: {} moduli, Q ~ 2^{:.1} > 2*B_rec; exact dot = {} (consensus weight {CONSENSUS_WEIGHT})",
        profile.moduli.len(),
        (profile.reconstruction_modulus()? as f64).log2(),
        dot
    );

    // Worked budget of eq. (7.17): D = F_base + v_exec + v_DA + v_ref = 100 PLAU.
    let job = JobId(1);
    let (deposit, queue_fee, base_fee) = (plau(100)?, plau(1)?, plau(10)?);
    ledger.escrow_fund_and_queue(job, deposit, queue_fee)?;
    step(
        &ledger,
        "ESCROW_FUND_AND_QUEUE",
        format!("D = {deposit}, f_queue = {queue_fee}"),
    )?;
    ledger.job_admit_and_lease(job, base_fee)?;
    step(
        &ledger,
        "JOB_ADMIT_AND_LEASE",
        format!("Base Fee {base_fee} -> R_l (irretrievable)"),
    )?;
    ledger.result_settle(job, plau(80)?, plau(5)?, plau(5)?)?;
    step(
        &ledger,
        "RESULT_SETTLE",
        "v_exec 80 + v_DA 5 + v_ref 5 PLAU -> U".to_string(),
    )?;

    let maturity_epoch = ledger
        .locked_fees()
        .iter()
        .map(|f| f.maturity_epoch)
        .max()
        .ok_or("no locked fees")?;
    let maturity_height =
        ledger.params().genesis_height + maturity_epoch * ledger.params().blocks_per_epoch;
    ledger.advance_to(maturity_height)?;
    let (_, matured) = ledger.reserve_mature()?;
    step(
        &ledger,
        "RESERVE_MATURE",
        format!(
            "h={maturity_height} (epoch {maturity_epoch}): {} lots R_l -> R_a",
            matured.len()
        ),
    )?;

    let (_, epoch) = ledger.book_epoch(&weights)?;
    ledger.fw_reward(epoch.booked)?;
    step(
        &ledger,
        "FW_REWARD (epoch with fee lots)",
        format!("{} paid from {} lots", epoch.booked, epoch.lots.len()),
    )?;
    for lot in epoch.lots.iter().filter(|l| matured.contains(&l.lot)) {
        let source = ledger
            .fee_lots()
            .iter()
            .find(|l| l.id() == lot.lot)
            .map_or(Atoms::ZERO, |l| l.source_fee());
        println!(
            "    fee lot #{} (F_c = {source}): budget {} atoms = {} booked + {} dust (segregated)",
            lot.lot.0,
            group(lot.budget.get()),
            group(lot.booked.get()),
            lot.dust.get()
        );
    }
    ledger.check_invariants()?;
    println!();
    print_categories(&ledger);

    // ---------------------------------------------------------------- (e)
    print_summary(&ledger, &ids, &allocation, matured.len(), epoch.dust)?;
    Ok(())
}

// ---------------------------------------------------------------------------
// Mock inputs
// ---------------------------------------------------------------------------

fn tag(name: &str) -> DomainSeparatedHash {
    DomainSeparatedHash::new("POC/MOCK/v2", &[name.as_bytes()])
}

fn mock_context(height: u64, attempt_nonce: u64) -> FreshWorkContext {
    FreshWorkContext {
        chain_id: 0x504c_4155, // "PLAU"
        genesis_id: tag("genesis"),
        protocol_version: 2,
        crypto_suite_id: 1,
        program_id: tag("fresh-work-program"),
        air_id: tag("int8-tile-air"),
        generator_version: 2,
        parent_canonical_id: tag("block-0"),
        stable_anchor_id: tag("anchor-0"),
        height,
        miner_policy_digest: tag("miner-policy"),
        payout_policy_digest: tag("payout-policy"),
        attempt_nonce,
        body_core_root: tag("body-core-1"),
        parent_derived_difficulty_context: tag("difficulty-0"),
        time_bucket: height * ledger::BLOCK_INTERVAL_SECONDS,
    }
}

/// The fresh share plus five mature shares from other miners. Owner 2 holds
/// two ShareIDs: its slots are simply the sum over them.
fn mock_cohort(fresh: DomainSeparatedHash) -> Vec<ShareID> {
    let mut shares = vec![ShareID {
        id: fresh,
        weight: 1_000_003,
        owner: OwnerId(1),
    }];
    for (i, (weight, owner)) in [
        (2_400_017u64, 2u64),
        (700_001, 2),
        (1_600_009, 3),
        (300_007, 4),
        (999_983, 5),
    ]
    .into_iter()
    .enumerate()
    {
        shares.push(ShareID {
            id: tag(&format!("mature-share-{i}")),
            weight,
            owner: OwnerId(owner),
        });
    }
    shares
}

/// Deterministic scaled integer operands with |x|, |y| < 2^23.
fn mock_scientific_operands() -> (Vec<f64>, Vec<f64>) {
    let operands = |mul: u64| -> Vec<f64> {
        (0..TILE_DIM as u64)
            .map(|i| ((i.wrapping_mul(mul) >> 7) % (1 << 24)) as f64 - (1 << 23) as f64)
            .collect()
    };
    (operands(2_654_435_761), operands(40_503))
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

fn plau(n: u64) -> PocResult<Atoms> {
    Atoms::from_plau(n).ok_or_else(|| "PLAU amount overflows".into())
}

fn ensure(condition: bool, message: &str) -> PocResult<()> {
    if condition {
        Ok(())
    } else {
        Err(message.into())
    }
}

fn section(letter: &str, title: &str) {
    println!("({letter}) {title}");
}

/// Reports one operation and re-checks the supply after it.
fn step(ledger: &Ledger, op: &str, detail: String) -> PocResult<()> {
    ensure(
        ledger.total() == u128::from(TOTAL_SUPPLY.get()),
        "supply changed",
    )?;
    println!("  {op:<32} {detail}");
    Ok(())
}

fn group(n: u64) -> String {
    let digits = n.to_string();
    let mut out = String::with_capacity(digits.len() + digits.len() / 3);
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (digits.len() - i).is_multiple_of(3) {
            out.push(',');
        }
        out.push(c);
    }
    out
}

fn print_categories(ledger: &Ledger) {
    let rule = "  +-----------------+-----------+---------------------------+";
    println!("{rule}");
    println!(
        "  | {:<15} | {:<9} | {:>25} |",
        "Category", "Symbol", "Balance (atoms)"
    );
    println!("{rule}");
    for category in StateCategory::ALL {
        println!(
            "  | {:<15} | {:<9} | {:>25} |",
            format!("{category:?}"),
            category.symbol(),
            group(ledger.balance(category).get())
        );
    }
    println!("{rule}");
    let total = ledger.total() as u64;
    let verdict = if u128::from(total) == u128::from(TOTAL_SUPPLY.get()) {
        "== M"
    } else {
        "!= M"
    };
    println!(
        "  | {:<15} | {:<9} | {:>25} |",
        "SUM",
        verdict,
        group(total)
    );
    println!("{rule}\n");
}

fn print_allocation(shares: &[ShareID], allocation: &Allocation) {
    let rule = "  +----+--------------------+-------+-----------+-------+";
    println!("{rule}");
    println!("  | #  | ShareID            | Owner | Weight    | Slots |");
    println!("{rule}");
    for (i, (share, slots)) in shares.iter().zip(&allocation.per_share).enumerate() {
        println!(
            "  | {i:<2} | {}.. | {:<5} | {:>9} | {slots:>5} |",
            share.id.short_hex(8),
            share.owner.0,
            group(share.weight)
        );
    }
    println!("{rule}");
    let order: Vec<String> = allocation.slots.iter().map(|s| s.to_string()).collect();
    println!("  lease order (slot -> share #): {}\n", order.join(" "));
}

fn print_summary(
    ledger: &Ledger,
    ids: &FreshWorkIds,
    allocation: &Allocation,
    matured_lots: usize,
    epoch_dust: Atoms,
) -> PocResult<()> {
    const WIDTH: usize = 72;
    let border = format!("+{}+", "=".repeat(WIDTH));
    let rule = format!("+{}+", "-".repeat(WIDTH));
    let line = |key: &str, value: String| println!("| {key:<20}: {value:<w$}|", w = WIDTH - 23);
    let distinct = allocation.per_share.iter().filter(|&&a| a > 0).count();
    let vested = ledger
        .founder_vesting()
        .completed_intervals(ledger.height());

    println!("{border}");
    println!("|{:^WIDTH$}|", "PLAUTHIUM BLOCK EXECUTED SUCCESSFULLY");
    println!("{border}");
    line(
        "Block height",
        format!("{BLOCK_HEIGHT} (state advanced to h={})", ledger.height()),
    );
    line("BlockID", format!("{}..", ids.block_id.short_hex(16)));
    line(
        "WorkID = ShareID",
        format!("{}..", ids.work_id.short_hex(16)),
    );
    line(
        "Work unit",
        format!(
            "{TILE_DIM}x{TILE_DIM} INT8 -> INT32, |Z| <= {}",
            group(ACCUMULATION_BOUND as u64)
        ),
    );
    line(
        "Freivalds",
        format!(
            "ACCEPT, r_F = {DEFAULT_FREIVALDS_ROUNDS}, {} F_p mults (9/256)",
            group(FREIVALDS_FIELD_MULS)
        ),
    );
    line(
        "D'Hondt leases",
        format!(
            "{}/{LEASE_SLOTS} slots -> {distinct} discrete ShareIDs",
            allocation.assigned()
        ),
    );
    line(
        "Fee lots matured",
        format!("{matured_lots} (queue fee + Base Fee), R_l -> R_a"),
    );
    line(
        "Dust this epoch",
        format!(
            "{} atoms (total segregated {})",
            epoch_dust.get(),
            ledger.segregated_dust().get()
        ),
    );
    line(
        "Founder vesting",
        format!(
            "{vested}/{VESTING_TRANCHES} tranches unlocked ({} days x {BLOCKS_PER_DAY} blocks)",
            vested
        ),
    );
    line(
        "Founder locked",
        format!(
            "{} of {} atoms",
            group(ledger.founder_vesting().locked_at(ledger.height()).get()),
            group(FOUNDER_ALLOCATION.get())
        ),
    );
    println!("{rule}");
    for category in StateCategory::ALL {
        line(
            category.symbol(),
            format!(
                "{:<16}{:>25}",
                format!("{category:?}"),
                group(ledger.balance(category).get())
            ),
        );
    }
    println!("{rule}");
    let total = ledger.total();
    ensure(
        total == u128::from(TOTAL_SUPPLY.get()),
        "supply invariant violated",
    )?;
    line(
        "SUM (== M)",
        format!("{:<16}{:>25}  OK", "", group(total as u64)),
    );
    println!("{border}");
    Ok(())
}
EOF

cat << 'EOF' > primitives/Cargo.toml
[package]
name = "primitives"
version = "0.1.0"
edition = "2024"
description = "Plauthium shared primitives: atoms, supply, Mersenne-61 field, domain-separated hashing, block resources"

[dependencies]

[lints]
workspace = true
EOF

cat << 'EOF' > primitives/src/lib.rs
//! Shared Plauthium primitives.
//!
//! Every consensus quantity is an integer (spec §1.4): amounts are [`Atoms`],
//! field arithmetic is over [`Mersenne61`], and every committed object is a
//! 512-bit [`DomainSeparatedHash`] of a typed, length-prefixed encoding.
//!
//! **PoC status:** [`DomainSeparatedHash`] and [`MockXof`] are deterministic,
//! *non-cryptographic* placeholders for SHA3-512 and SHAKE256. They keep the
//! normative interface (label, injective encoding, 64-byte digests) so that the
//! real primitives can be swapped in without touching callers.

use core::fmt;
use core::ops::{Add, AddAssign, Mul, Neg, Sub};

// ---------------------------------------------------------------------------
// Amounts and supply (spec §7.6, eq. 7.18)
// ---------------------------------------------------------------------------

/// Number of atoms in one PLAU (`1 TKN = 10^8 atoms`).
pub const ATOMS_PER_PLAU: u64 = 100_000_000;

/// Fixed supply in whole PLAU.
pub const TOTAL_SUPPLY_PLAU: u64 = 15_000_000;

/// Fixed supply `M = 1.5 * 10^15` atoms. It never changes in any reachable state.
pub const TOTAL_SUPPLY: Atoms = Atoms(1_500_000_000_000_000);

// `M = 15,000,000 PLAU` and `M < 2^51 < p`; evaluated at compile time, so an
// overflow or a violated bound fails the build.
const _: () = assert!(TOTAL_SUPPLY_PLAU * ATOMS_PER_PLAU == TOTAL_SUPPLY.0);
const _: () = assert!(TOTAL_SUPPLY.0 < (1u64 << 51));
const _: () = assert!((1u64 << 51) < Mersenne61::P);

/// An integer amount of the single native asset, in atoms.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Atoms(pub u64);

impl Atoms {
    /// Zero atoms.
    pub const ZERO: Atoms = Atoms(0);

    /// Converts whole PLAU to atoms, or `None` on overflow.
    pub const fn from_plau(plau: u64) -> Option<Atoms> {
        match plau.checked_mul(ATOMS_PER_PLAU) {
            Some(atoms) => Some(Atoms(atoms)),
            None => None,
        }
    }

    /// The raw atom count.
    pub const fn get(self) -> u64 {
        self.0
    }

    /// Checked addition.
    pub const fn checked_add(self, rhs: Atoms) -> Option<Atoms> {
        match self.0.checked_add(rhs.0) {
            Some(v) => Some(Atoms(v)),
            None => None,
        }
    }

    /// Checked subtraction.
    pub const fn checked_sub(self, rhs: Atoms) -> Option<Atoms> {
        match self.0.checked_sub(rhs.0) {
            Some(v) => Some(Atoms(v)),
            None => None,
        }
    }
}

impl fmt::Display for Atoms {
    /// Formats as PLAU with all eight decimal places, e.g. `10.00000000 PLAU`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{}.{:08} PLAU",
            self.0 / ATOMS_PER_PLAU,
            self.0 % ATOMS_PER_PLAU
        )
    }
}

/// Integer Fresh Work share weight `w_s` (spec §6.1).
///
/// **PoC width:** normatively `w_s = floor(2^640 / Θ_S(s))`, an integer of up
/// to 640 bits. The PoC narrows it to `u64` so that every product with a slot
/// counter (D'Hondt) or an atom budget (fee-lot payouts) is exact in `u128`.
pub type ShareWeight = u64;

// ---------------------------------------------------------------------------
// Base field F_p, p = 2^61 - 1 (spec §3.1, Table 1)
// ---------------------------------------------------------------------------

/// An element of the base field `F_p`, `p = 2^61 - 1`, kept canonical in `[0, p)`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Mersenne61(u64);

impl Mersenne61 {
    /// The Mersenne prime `p = 2^61 - 1 = 2,305,843,009,213,693,951`.
    pub const P: u64 = (1u64 << 61) - 1;
    /// Additive identity.
    pub const ZERO: Mersenne61 = Mersenne61(0);
    /// Multiplicative identity.
    pub const ONE: Mersenne61 = Mersenne61(1);

    /// Reduces any `u64` into the field.
    pub const fn new(value: u64) -> Self {
        Mersenne61(Self::reduce_u128(value as u128))
    }

    /// Centered lift of a signed integer: negative values map to `p - |v| mod p`.
    pub const fn from_i64(value: i64) -> Self {
        let magnitude = Self::new(value.unsigned_abs());
        if value < 0 {
            magnitude.neg_const()
        } else {
            magnitude
        }
    }

    /// The canonical representative in `[0, p)`.
    pub const fn value(self) -> u64 {
        self.0
    }

    /// Reduces any `u128` modulo `p` using `2^61 = 1 (mod p)`.
    pub const fn reduce_u128(x: u128) -> u64 {
        let p = Self::P as u128;
        // x < 2^128  =>  folded < 2^61 + 2^67  =>  refolded < 2^61 + 2^7 < 2p.
        let folded = (x & p) + (x >> 61);
        let refolded = ((folded & p) + (folded >> 61)) as u64;
        if refolded >= Self::P {
            refolded - Self::P
        } else {
            refolded
        }
    }

    const fn neg_const(self) -> Self {
        if self.0 == 0 {
            self
        } else {
            Mersenne61(Self::P - self.0)
        }
    }
}

impl Add for Mersenne61 {
    type Output = Self;
    fn add(self, rhs: Self) -> Self {
        // Both operands < 2^61, so the sum < 2^62 cannot overflow.
        Mersenne61::new(self.0 + rhs.0)
    }
}

impl AddAssign for Mersenne61 {
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

impl Sub for Mersenne61 {
    type Output = Self;
    fn sub(self, rhs: Self) -> Self {
        self + (-rhs)
    }
}

impl Neg for Mersenne61 {
    type Output = Self;
    fn neg(self) -> Self {
        self.neg_const()
    }
}

impl Mul for Mersenne61 {
    type Output = Self;
    fn mul(self, rhs: Self) -> Self {
        Mersenne61(Self::reduce_u128(self.0 as u128 * rhs.0 as u128))
    }
}

// ---------------------------------------------------------------------------
// Domain-separated hashing (spec §1.4, eq. 1.3) — PLACEHOLDER for SHA3-512
// ---------------------------------------------------------------------------

/// Digest length of SHA3-512 in bytes.
pub const DIGEST_LEN: usize = 64;

/// Versioned domain labels fixed by the specification.
pub mod labels {
    /// Fresh Work seed, eq. (5.2).
    pub const FW_INPUT: &str = "FW/INPUT/v2";
    /// Expansion domain of the left operand `X`, eq. (5.3).
    pub const FW_A: &str = "FW/A";
    /// Expansion domain of the right operand `Y`, eq. (5.3).
    pub const FW_B: &str = "FW/B";
    /// Commitment to the canonical product `XY`, eq. (5.4).
    pub const FW_OUTPUT: &str = "FW/OUTPUT/v2";
    /// Work identifier, which is also the ShareID, eq. (5.4).
    pub const FW_ID: &str = "FW/ID/v2";
    /// Identifier of the block an attempt would seal, eq. (5.4).
    pub const BLOCK: &str = "BLOCK/v2";
    /// Share lottery value, eq. (5.5).
    pub const FW_SHARE: &str = "FW/SHARE/v2";
    /// Seal lottery value, eq. (5.5).
    pub const FW_SEAL: &str = "FW/SEAL/v2";
    /// Transaction effect identifier, eq. (7.5).
    pub const TX_EFFECTS: &str = "TX/EFFECTS/v2";
    /// Signature context string, eqs. (2.3)–(2.5).
    pub const PLAU_TX: &str = "PLAU/TX/v2";
    /// Freivalds challenge domain. The spec requires one domain per round
    /// (§3.2) but does not name it; this label is assigned by the PoC.
    pub const FW_FREIVALDS: &str = "FW/FREIVALDS/v2";
}

/// A 512-bit digest `H_512(Enc(LABEL/v2, f_1, ..., f_k))`.
///
/// Ordering is lexicographic over the 64 bytes, which equals the numeric order
/// of the digest read as a big-endian integer (spec §1.4) and the canonical
/// 64-byte-string order used for ShareID tie-breaks (spec §6.3).
///
/// **PLACEHOLDER:** the compression function is a non-cryptographic mixer.
/// Replace with SHA3-512 (FIPS 202) before any security claim is made.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct DomainSeparatedHash([u8; DIGEST_LEN]);

impl DomainSeparatedHash {
    /// Hashes `fields` under `label` with the injective encoding of [`DomainHasher`].
    pub fn new(label: &str, fields: &[&[u8]]) -> Self {
        let mut hasher = DomainHasher::new(label);
        for field in fields {
            hasher.field(field);
        }
        hasher.finalize()
    }

    /// Wraps raw digest bytes.
    pub const fn from_bytes(bytes: [u8; DIGEST_LEN]) -> Self {
        DomainSeparatedHash(bytes)
    }

    /// The digest bytes, big-endian.
    pub const fn as_bytes(&self) -> &[u8; DIGEST_LEN] {
        &self.0
    }

    /// The digest bytes by value; inverse of [`DomainSeparatedHash::from_bytes`].
    pub const fn to_bytes(&self) -> [u8; DIGEST_LEN] {
        self.0
    }

    /// Full lowercase hex encoding (128 characters).
    pub fn to_hex(&self) -> String {
        self.0.iter().map(|b| format!("{b:02x}")).collect()
    }

    /// First `bytes` bytes as hex, for logs and summaries.
    pub fn short_hex(&self, bytes: usize) -> String {
        self.0[..bytes.min(DIGEST_LEN)]
            .iter()
            .map(|b| format!("{b:02x}"))
            .collect()
    }
}

impl fmt::Debug for DomainSeparatedHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "H512({}..)", self.short_hex(8))
    }
}

/// Incremental builder for `H_512(Enc(label, f_1, ..., f_k))`.
///
/// `Enc` is injective: the label and every field are prefixed by their byte
/// length as a big-endian `u64`, and the field count is bound at finalization.
/// Field order is fixed by each call site, as the spec requires.
#[derive(Clone)]
pub struct DomainHasher {
    sponge: MockSponge,
    fields: u64,
}

impl DomainHasher {
    /// Starts a hash under a versioned domain label.
    pub fn new(label: &str) -> Self {
        let mut sponge = MockSponge::new();
        sponge.absorb(&(label.len() as u64).to_be_bytes());
        sponge.absorb(label.as_bytes());
        DomainHasher { sponge, fields: 0 }
    }

    /// Appends one length-prefixed byte field.
    pub fn field(&mut self, bytes: &[u8]) -> &mut Self {
        self.begin_field(bytes.len());
        self.sponge.absorb(bytes);
        self
    }

    /// Appends a `u64` field (8 bytes, big-endian).
    pub fn field_u64(&mut self, value: u64) -> &mut Self {
        self.field(&value.to_be_bytes())
    }

    /// Appends a digest field.
    pub fn field_digest(&mut self, digest: &DomainSeparatedHash) -> &mut Self {
        self.field(digest.as_bytes())
    }

    /// Appends a field of `i8` values, one byte each (two's complement).
    pub fn field_i8s(&mut self, values: &[i8]) -> &mut Self {
        self.begin_field(values.len());
        for &v in values {
            self.sponge.absorb_byte(v as u8);
        }
        self
    }

    /// Appends a field of `i32` values, four big-endian bytes each.
    pub fn field_i32s(&mut self, values: &[i32]) -> &mut Self {
        self.begin_field(values.len() * 4);
        for &v in values {
            self.sponge.absorb(&v.to_be_bytes());
        }
        self
    }

    /// Completes the encoding and returns the digest.
    pub fn finalize(&self) -> DomainSeparatedHash {
        let mut sponge = self.sponge.clone();
        sponge.absorb(&self.fields.to_be_bytes());
        DomainSeparatedHash(sponge.squeeze())
    }

    fn begin_field(&mut self, byte_len: usize) {
        self.fields += 1;
        self.sponge.absorb(&(byte_len as u64).to_be_bytes());
    }
}

/// Extendable-output stream bound to a label and a seed.
///
/// **PLACEHOLDER** for `SHAKE256(Enc(label, seed))`; output block `i` is
/// `H_512(Enc(label, seed, i))` of the placeholder hash.
#[derive(Clone)]
pub struct MockXof {
    prefix: DomainHasher,
    counter: u64,
    block: [u8; DIGEST_LEN],
    offset: usize,
}

impl MockXof {
    /// Starts a stream for `label` and `seed`.
    pub fn new(label: &str, seed: &DomainSeparatedHash) -> Self {
        let mut prefix = DomainHasher::new(label);
        prefix.field_digest(seed);
        MockXof {
            prefix,
            counter: 0,
            block: [0; DIGEST_LEN],
            offset: DIGEST_LEN,
        }
    }

    /// Next output byte.
    pub fn next_byte(&mut self) -> u8 {
        if self.offset == DIGEST_LEN {
            let mut block = self.prefix.clone();
            block.field_u64(self.counter);
            self.block = *block.finalize().as_bytes();
            self.counter += 1;
            self.offset = 0;
        }
        let byte = self.block[self.offset];
        self.offset += 1;
        byte
    }

    /// Next eight output bytes as a big-endian `u64`.
    pub fn next_u64(&mut self) -> u64 {
        let mut bytes = [0u8; 8];
        for b in &mut bytes {
            *b = self.next_byte();
        }
        u64::from_be_bytes(bytes)
    }
}

const SPONGE_LANES: usize = 8;
const GOLDEN_GAMMA: u64 = 0x9e37_79b9_7f4a_7c15;

/// Non-cryptographic 512-bit state used by the hashing placeholders.
#[derive(Clone)]
struct MockSponge {
    lanes: [u64; SPONGE_LANES],
    buffer: [u8; 8],
    buffered: usize,
    absorbed: u64,
}

impl MockSponge {
    fn new() -> Self {
        let mut lanes = [0u64; SPONGE_LANES];
        for (i, lane) in lanes.iter_mut().enumerate() {
            *lane = mix64(GOLDEN_GAMMA.wrapping_mul(i as u64 + 1));
        }
        MockSponge {
            lanes,
            buffer: [0; 8],
            buffered: 0,
            absorbed: 0,
        }
    }

    fn absorb(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.absorb_byte(b);
        }
    }

    fn absorb_byte(&mut self, byte: u8) {
        self.buffer[self.buffered] = byte;
        self.buffered += 1;
        self.absorbed = self.absorbed.wrapping_add(1);
        if self.buffered == 8 {
            self.absorb_word(u64::from_le_bytes(self.buffer));
            self.buffered = 0;
        }
    }

    fn absorb_word(&mut self, word: u64) {
        for i in 0..SPONGE_LANES {
            let neighbour = self.lanes[(i + SPONGE_LANES - 1) % SPONGE_LANES];
            self.lanes[i] = mix64(self.lanes[i] ^ word ^ neighbour.rotate_left(17));
        }
    }

    fn squeeze(mut self) -> [u8; DIGEST_LEN] {
        let absorbed = self.absorbed;
        self.absorb_byte(0x80);
        while self.buffered != 0 {
            self.absorb_byte(0);
        }
        self.absorb_word(absorbed);
        for _ in 0..SPONGE_LANES {
            self.absorb_word(GOLDEN_GAMMA);
        }
        let mut out = [0u8; DIGEST_LEN];
        for (chunk, lane) in out.chunks_exact_mut(8).zip(self.lanes) {
            chunk.copy_from_slice(&lane.to_be_bytes());
        }
        out
    }
}

/// SplitMix64 finalizer.
const fn mix64(mut z: u64) -> u64 {
    z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    z ^ (z >> 31)
}

// ---------------------------------------------------------------------------
// Post-quantum object sizes (spec Table 3) and block resources (spec §7.10)
// ---------------------------------------------------------------------------

/// Genesis-suite object sizes in bytes (spec Table 3).
pub mod pq_sizes {
    /// ML-DSA-87 public key.
    pub const ML_DSA_87_PUBLIC_KEY: u64 = 2_592;
    /// ML-DSA-87 signature.
    pub const ML_DSA_87_SIGNATURE: u64 = 4_627;
    /// SLH-DSA-SHAKE-256s public key.
    pub const SLH_DSA_SHAKE_256S_PUBLIC_KEY: u64 = 64;
    /// SLH-DSA-SHAKE-256s signature.
    pub const SLH_DSA_SHAKE_256S_SIGNATURE: u64 = 29_792;
    /// ML-KEM-1024 encapsulation key.
    pub const ML_KEM_1024_ENCAPSULATION_KEY: u64 = 1_568;
    /// ML-KEM-1024 ciphertext.
    pub const ML_KEM_1024_CIPHERTEXT: u64 = 1_568;
}

/// The five-component block resource vector `(B_bytes, B_sig, B_ZK, B_state, B_DA)`
/// of eq. (7.31). A block is valid only if the sum of its transactions' vectors
/// is componentwise at most the block limit.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct BlockResourceVector {
    /// Serialized bytes, including post-quantum signatures and keys.
    pub bytes: u64,
    /// Signature verifications.
    pub signature_checks: u64,
    /// Zero-knowledge proof verifications.
    pub zk_checks: u64,
    /// State writes.
    pub state_writes: u64,
    /// Data-availability payload bytes.
    pub da_bytes: u64,
}

impl BlockResourceVector {
    /// The zero vector.
    pub const ZERO: BlockResourceVector = BlockResourceVector {
        bytes: 0,
        signature_checks: 0,
        zk_checks: 0,
        state_writes: 0,
        da_bytes: 0,
    };

    /// Componentwise checked sum.
    pub fn checked_add(&self, other: &Self) -> Option<Self> {
        Some(BlockResourceVector {
            bytes: self.bytes.checked_add(other.bytes)?,
            signature_checks: self.signature_checks.checked_add(other.signature_checks)?,
            zk_checks: self.zk_checks.checked_add(other.zk_checks)?,
            state_writes: self.state_writes.checked_add(other.state_writes)?,
            da_bytes: self.da_bytes.checked_add(other.da_bytes)?,
        })
    }

    /// The componentwise order `self ≼ limit`.
    pub fn fits_within(&self, limit: &Self) -> bool {
        self.bytes <= limit.bytes
            && self.signature_checks <= limit.signature_checks
            && self.zk_checks <= limit.zk_checks
            && self.state_writes <= limit.state_writes
            && self.da_bytes <= limit.da_bytes
    }

    /// Sums transaction vectors and checks the block limit; `None` if any
    /// component overflows or exceeds its limit.
    pub fn accumulate<'a>(
        txs: impl IntoIterator<Item = &'a BlockResourceVector>,
        limit: &Self,
    ) -> Option<Self> {
        let total = txs
            .into_iter()
            .try_fold(Self::ZERO, |acc, tx| acc.checked_add(tx))?;
        total.fits_within(limit).then_some(total)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn total_supply_fits_in_u64_without_overflow() {
        let computed = TOTAL_SUPPLY_PLAU
            .checked_mul(ATOMS_PER_PLAU)
            .expect("15,000,000 PLAU * 10^8 must not overflow u64");
        assert_eq!(computed, 1_500_000_000_000_000);
        assert_eq!(Atoms::from_plau(TOTAL_SUPPLY_PLAU), Some(TOTAL_SUPPLY));
        // Headroom: M < 2^51 < p, so supply sums never alias in F_p.
        assert!(TOTAL_SUPPLY.get() < 1 << 51);
        assert!(u128::from(TOTAL_SUPPLY.get()) < u128::from(Mersenne61::P));
        // Even M summed with itself 4096 times stays inside u64.
        assert!(TOTAL_SUPPLY.get().checked_mul(4096).is_some());
    }

    #[test]
    fn atoms_arithmetic_and_display() {
        assert_eq!(ATOMS_PER_PLAU, 100_000_000);
        assert_eq!(Atoms::from_plau(u64::MAX), None);
        assert_eq!(Atoms(5).checked_sub(Atoms(6)), None);
        assert_eq!(Atoms(u64::MAX).checked_add(Atoms(1)), None);
        assert_eq!(Atoms(1_000_000_001).to_string(), "10.00000001 PLAU");
        assert_eq!(TOTAL_SUPPLY.to_string(), "15000000.00000000 PLAU");
    }

    #[test]
    fn mersenne61_constant_and_arithmetic() {
        assert_eq!(Mersenne61::P, 2_305_843_009_213_693_951);
        assert_eq!(Mersenne61::new(Mersenne61::P), Mersenne61::ZERO);
        assert_eq!(Mersenne61::new(Mersenne61::P + 5).value(), 5);
        assert_eq!(Mersenne61::new(u64::MAX).value(), u64::MAX % Mersenne61::P);
        let minus_one = Mersenne61::from_i64(-1);
        assert_eq!(minus_one.value(), Mersenne61::P - 1);
        assert_eq!(minus_one + Mersenne61::ONE, Mersenne61::ZERO);
        assert_eq!(minus_one * minus_one, Mersenne61::ONE);
        assert_eq!(
            Mersenne61::from_i64(-127) + Mersenne61::new(127),
            Mersenne61::ZERO
        );
        assert_eq!(
            Mersenne61::new(3) - Mersenne61::new(5),
            Mersenne61::from_i64(-2)
        );
        // Spot-check reduction against plain u128 remainders.
        for &(a, b) in &[
            (Mersenne61::P - 1, Mersenne61::P - 2),
            (1 << 60, 1 << 60),
            (12345, 67890),
        ] {
            let expected = ((a as u128 * b as u128) % Mersenne61::P as u128) as u64;
            assert_eq!((Mersenne61::new(a) * Mersenne61::new(b)).value(), expected);
        }
        assert_eq!(
            Mersenne61::reduce_u128(u128::MAX),
            (u128::MAX % Mersenne61::P as u128) as u64
        );
    }

    #[test]
    fn domain_separated_hash_is_deterministic_and_separated() {
        let a = DomainSeparatedHash::new(labels::FW_SHARE, &[b"work"]);
        assert_eq!(a, DomainSeparatedHash::new(labels::FW_SHARE, &[b"work"]));
        assert_ne!(a, DomainSeparatedHash::new(labels::FW_SEAL, &[b"work"]));
        // Length prefixes make the encoding injective across field boundaries.
        assert_ne!(
            DomainSeparatedHash::new(labels::FW_ID, &[b"ab", b"c"]),
            DomainSeparatedHash::new(labels::FW_ID, &[b"a", b"bc"])
        );
        assert_ne!(
            DomainSeparatedHash::new(labels::FW_ID, &[b""]),
            DomainSeparatedHash::new(labels::FW_ID, &[])
        );
        assert_eq!(a.to_hex().len(), 2 * DIGEST_LEN);
    }

    #[test]
    fn xof_is_deterministic_and_seed_bound() {
        let seed = DomainSeparatedHash::new(labels::FW_INPUT, &[b"x"]);
        let mut one = MockXof::new(labels::FW_A, &seed);
        let mut two = MockXof::new(labels::FW_A, &seed);
        let mut other = MockXof::new(labels::FW_B, &seed);
        let a: Vec<u8> = (0..200).map(|_| one.next_byte()).collect();
        let b: Vec<u8> = (0..200).map(|_| two.next_byte()).collect();
        let c: Vec<u8> = (0..200).map(|_| other.next_byte()).collect();
        assert_eq!(a, b);
        assert_ne!(a, c);
    }

    #[test]
    fn block_resource_vector_is_componentwise() {
        let limit = BlockResourceVector {
            bytes: 100_000,
            signature_checks: 10,
            zk_checks: 2,
            state_writes: 50,
            da_bytes: 1 << 20,
        };
        let tx = BlockResourceVector {
            bytes: pq_sizes::ML_DSA_87_SIGNATURE + pq_sizes::ML_DSA_87_PUBLIC_KEY,
            signature_checks: 1,
            zk_checks: 0,
            state_writes: 3,
            da_bytes: 0,
        };
        let total = BlockResourceVector::accumulate([tx; 10].iter(), &limit).unwrap();
        assert_eq!(total.signature_checks, 10);
        // An eleventh signature check breaks one component, even though the
        // other four still have headroom.
        assert!(BlockResourceVector::accumulate([tx; 11].iter(), &limit).is_none());
        let zk_heavy = BlockResourceVector {
            zk_checks: 3,
            ..BlockResourceVector::ZERO
        };
        assert!(!zk_heavy.fits_within(&limit));
    }
}
